// 简体中文 stories: I18N["zh-CN"].stories["<civ id>:<activity>"] = "…" (same keys as cultures/stories/europe-west.js).
Object.assign(I18N["zh-CN"].stories, {
  "britons:hunt": "约940年成文的海韦尔·达（Hywel Dda）威尔士法典规定，国王的首席猎手（pencynydd）在大厅中有一席之地，每张兽皮都可分得一份。国王一条训练有素的猎犬价值整整一镑，抵得上好几头牛。秋天，猎手们带着号角和牵绳骑入橡树谷地追逐雄鹿，他们知道，冬日餐桌上的肉食和自己的荣誉，都系于这一趟。",
  "britons:battle": "约600年，戈多丁（Gododdin）的勇士们在丁埃丁（Din Eidyn）饮了领主一整年的蜜酒，随后南下卡特雷斯（Catraeth）迎战盎格鲁人。诗人阿内林（Aneirin）唱道：三百人出征，佩着金项圈，谈笑风生，归来者却寥寥无几。《戈多丁》（Y Gododdin）并非凯歌。它逐一称颂每位阵亡者的名字，蜜酒之债由此偿清，记忆由此留存。",
  "britons:gather": "在彭布罗克郡（Sir Benfro）和锡尔迪金（Ceredigion），田里最后一把麦穗会被编在一起，称作“y wrach”，即“老巫婆”。收割者退后几步，轮流把镰刀掷向它；谁割下了它，就得把它干干地带回农舍，而女人们正提着水桶守在门口。收获就在欢笑、一身湿透和一场犒劳汗水的盛宴中结束。",
  "britons:ritual": "在冬季前夜（Nos Galan Gaeaf），威尔士村民在山上燃起篝火，每人投入一块做了记号的白石。他们绕火而行，然后赶在无尾黑母猪追上之前跑回家。黎明时分，人们在灰烬中寻找。找不到石头的人，便见不到下一个冬天。人们是平静地、而非惊恐地去探知这一年的命运。",
  "britons:rain": "想象：赶牛人带着黑牛聚集在兰多弗里（Llanymddyfri）上方，准备踏上通往英格兰集市的漫长旅途。浓雾笼罩着黑山（Y Mynydd Du），谁也不动身；牛群可能会走下山谷（cwm）的悬崖。男人们坐在石墙上，传着一支烟斗，低声唱着赞美诗。雨对他们不算什么。他们只等云雾散开，露出道路。",
  "britons:flood": "1607年1月30日清晨，一道水墙沿布里斯托尔海峡和塞文河（Hafren）涌来，淹没了格温特和格拉摩根（Morgannwg）的低地农庄，直至山脚。两岸约有两千人丧生。在戈德克利夫和雷德威克的教堂里，黄铜牌至今仍标示着海水涨到的高度。人们说这是上帝在说话；但他们照样重建了海堤。",
  "britons:wind": "1859年10月25日夜，一场飓风把从澳大利亚金矿归来的蒸汽快帆船“皇家宪章号”抛上了安格尔西岛（Ynys Môn）莫尔夫雷的礁石。约四百五十人遇难。村里的男人们手拉手结成人链冲进浪中，把幸存者拉上岸。查尔斯·狄更斯曾前来探访，写下那位牧师如何像对待自家亲人一样安葬这些溺亡的陌生人。",
  "britons:fire": "1400年9月18日，欧文·格林杜尔（Owain Glyndŵr）在格林迪弗尔迪被拥立为威尔士亲王（Tywysog Cymru），数日之内，他的人马便纵火焚烧了英格兰人的市镇鲁辛（Rhuthun）。集市摊位和木屋燃起大火，城堡却守住了。对威尔士人来说，这是被征服一个世纪之后长久希望的第一点火星；诗人们向他欢呼，克卢伊德河谷上空的浓烟被视为某种开端。",
  "britons:thunder": "想象：雷雨滚过埃里里（Eryri），高地农场的牧羊人一边把母羊从山坡上赶拢，一边数着雷声。一位老妇人说，山又在生铜矿工的气了。孩子们被叮嘱把镜子盖上。暴风雨过后，山谷脚下的礼拜堂里响起赞美诗，一半出于感恩，一半出于每个星期天的习惯。",
  "britons:birth": "1457年1月28日，在彭布罗克城堡（Castell Penfro），年仅十三岁、已经守寡的玛格丽特·博福特经过一场凶险的分娩生下一子。她此后再未生育。威尔士诗人很快唱起“预言之子”（mab darogan），说他将恢复古老的不列颠王冠。很少有人相信，这个羸弱的男孩亨利·都铎（Harri Tudur）会在博斯沃思结束玫瑰战争。",
  "britons:death": "在威尔士边区（y Gororau），葬礼上有时会请来一位“食罪人”。约翰·奥布里在1680年代记述：一个穷人站在棺旁，接过从遗体上方递过来的一条面包、一碗啤酒和六便士，从而把死者的罪揽到自己身上。随后家人彻夜守灵（gwylnos），唱着赞美诗，直到送葬前往墓地。",

  "english:hunt": "1100年8月2日，绰号“红脸”的国王威廉二世在新森林狩猎——那是他父亲清空村庄而辟出的王家森林。夕阳西沉时，沃尔特·蒂雷尔射向一头雄鹿的箭正中国王胸膛。蒂雷尔逃往法国。烧炭人用一辆大车把遗体运到温切斯特。许多英格兰人说，是森林报了仇，几乎没人落泪。",
  "english:battle": "1415年10月25日，圣克里斯宾节，亨利五世疲惫多病的军队在阿金库尔面对数量远胜于己的法军。雨水把犁过的田地变成了泥潭。长弓手们打下木桩，当法国重甲骑士在泥中艰难前行时，箭矢如雪片般落下。到傍晚，法国贵族的尸体堆积如山。英格兰唱起《感谢上帝，英格兰》（Deo gratias Anglia），并将此役铭记了六百年。",
  "english:gather": "托马斯·塔瑟的《良好农事五百条》（1573年）教英格兰农民如何收割庄稼，又如何庆祝“丰收归仓”。最后一车庄稼装在丰收车上运回，车上饰以绿枝和麦秆娃娃，收割者坐在顶上高声呼喊。农场主备下牛肉和葡萄干布丁的晚餐，主人与雇工一同饮酒，一年一次，平起平坐。",
  "english:ritual": "伊丽莎白一世加冕之前，她的顾问、数学家兼占星家约翰·迪伊受命推算星象、择定吉日。他选了1559年1月15日。迪伊后来多年通过一位通灵者寻求天使的讯息，希望知晓英格兰和世界的未来。而对大多数英格兰人来说，这个问题只是交给上帝，在《公祷书》中，一个星期天接一个星期天。",
  "english:rain": "1588年7月19日，有人在利泽德角外望见了西班牙无敌舰队。传说弗朗西斯·德雷克正在普利茅斯高地玩草地滚球，并坚持打完了这一局。真相是：逆风加上涨潮，英格兰舰队无法出港。除了等待退潮和风向转变，别无他法；当晚，他们用绞索把船只牵引到了海湾里。",
  "english:flood": "1953年1月31日夜，风暴潮漫过了英格兰东部的海堤。在泰晤士河口的坎维岛，一家家人醒来时发现水正从地板缝里往上涌；那里有五十八人遇难，整个沿岸则超过三百人。邻居们在黑暗中划船穿过街道。全国以沙袋和士兵回应，随后修建了泰晤士河水闸，不让悲剧重演。",
  "english:wind": "1703年11月26日至27日，大风暴横扫英格兰南部。烟囱倒塌，威斯敏斯特教堂顶上的铅皮被掀掉，数千名水手在古德温沙洲溺亡。修建了埃迪斯通灯塔的亨利·温斯坦利曾希望在史上最大的风暴中身处灯塔之内，那一夜他正在那里；后来他和灯塔都踪迹全无。丹尼尔·笛福收集目击者的来信，汇编出版为《风暴》。",
  "english:fire": "1666年9月2日凌晨，布丁巷托马斯·法里纳的面包房起火。干燥的东风推着大火在木结构的城市里烧了四天。塞缪尔·佩皮斯把他的葡萄酒和帕尔马干酪埋在花园里，眼看着圣保罗大教堂被烧毁。一万三千多栋房屋化为灰烬，但死者极少，雷恩随后用石头重建了教堂。",
  "english:thunder": "1638年10月21日星期日，达特穆尔的维德科姆教堂正在做下午礼拜，一场猛烈的雷暴击中了教堂。一团火球冲破窗户，塔楼的一部分砸穿屋顶，四人丧生。村民说，是魔鬼亲自来抓会众里一个爱打牌的男人。记录那一天的诗句至今仍挂在教堂里。",
  "english:birth": "1533年9月7日，安妮·博林在格林尼治生下一个女儿。亨利八世为了得到儿子不惜与罗马决裂；原本筹备的庆祝骑枪比武被悄悄取消。洗礼上没有人能想到，这个女孩伊丽莎白将统治四十四年，击退无敌舰队，并以她的名字命名一个时代。她的出生令一位国王失望，后来却令一个民族欢欣。",
  "english:death": "在英格兰的教区，有人去世时会敲响丧钟：孩子敲三下，女人六下，男人九下，即所谓“九裁缝”，然后按死者的年岁每岁一下。田里的人都停下手来数。1624年，约翰·多恩写道：“不要问丧钟为谁而鸣，它为你而鸣。”接着是黑布、送葬行列和教堂墓地。",

  "house-of-lancaster:hunt": "1406年至1413年间，约克公爵爱德华把一部法语狩猎书译成英文，题为《狩猎之主》，献给兰开斯特的亨利王子，即后来的亨利五世。书中描述了雄鹿、野猪和猎犬，并宣称狩猎能使人远离懒惰与罪恶。王子酷爱追猎。他加冕两年后，爱德华在阿金库尔战死在他身旁。",
  "house-of-lancaster:battle": "1461年3月29日棕枝主日，兰开斯特军在暴风雪中与约克军在陶顿交锋。风把雪吹向兰开斯特军的脸，他们的箭射程不足，而约克军的箭却纷纷命中。经过数小时的屠戮，战线崩溃，士兵们溺死在科克溪中。这或许是英格兰土地上最血腥的一天，亨利六世因此失去了王冠。",
  "house-of-lancaster:gather": "想象：米迦勒节时，兰开斯特公爵领各庄园的管事带着账卷骑马前往庞蒂弗拉克特，送来一年的租税，有钱币也有实物。成斗的燕麦、成车的羊毛和肥鹅挤满了城堡院子。总管用刻痕木签一一记账。这些钱将用来支付弓箭手和国王在法国的战争；村民们只盼着够用，好让士兵离他们远一点。",
  "house-of-lancaster:ritual": "1413年3月20日夜，父亲亨利四世刚刚去世，新王亨利五世独自前往威斯敏斯特教堂，在一位隐修士的小室中度过了一夜。编年史家说，他出来时已判若两人，抛下了年少时那些放荡的伙伴。他在向上帝询问自己该做怎样的国王，而他得到的答案，从未告诉任何人。",
  "house-of-lancaster:rain": "1485年夏，兰开斯特事业的最后希望亨利·都铎率领一支由流亡者和法国士兵组成的小军队，在阿夫勒尔等待。一切都取决于风。8月1日风向转了，他的船队向西启航；8月7日，他在米尔福德港附近的米尔湾登陆，跪在威尔士的土地上诵读诗篇。不到三周，他就成了国王。",
  "house-of-lancaster:flood": "1483年10月，白金汉公爵起兵反对理查三世，支持亨利·都铎。但连日大雨使塞文河暴涨，他的军队无法渡河；洪水淹死了牲畜和摇篮中的婴儿，长久被人们称为“白金汉大水”。他的部下纷纷散去，他本人遭人出卖，在索尔兹伯里被斩首。兰开斯特派的希望又等了两年。",
  "house-of-lancaster:wind": "同样在1483年10月，亨利·都铎从布列塔尼启航去响应起事。一场风暴在海峡中吹散了他的船队。当他的船终于抵达普尔时，他看见岸上的士兵以朋友的姿态邀他登陆。他怀疑有诈，扬帆返回法国。风暴使他输掉了这场叛乱，却也可能救了他一命。",
  "house-of-lancaster:fire": "1381年6月13日，农民起义的叛军闯入萨伏伊宫——兰开斯特家族之父冈特的约翰在伦敦的豪宅。他们痛恨他，视他为少年国王背后的掌权者。他们砸碎他的银器，把珠宝扔进泰晤士河，将宫殿烧成平地；一个被抓到偷东西的人被叛军自己扔进了火中。此后一个世纪，那里什么也没有重建。",
  "house-of-lancaster:thunder": "1402年，亨利四世率军进入威尔士讨伐欧文·格林杜尔。9月，一场狂风、冰雹和雷电交加的暴风雨猛烈袭击营地，国王的帐篷被吹倒，一支长矛险些要了他的命。英格兰编年史家说是格林杜尔用魔法召来了风暴。军队浑身湿透、饥肠辘辘地撤退，这位兰开斯特国王明白了：威尔士不会很快被征服。",
  "house-of-lancaster:birth": "1421年12月6日，瓦卢瓦的凯瑟琳在温莎生下一子。亨利五世当时正在围攻莫城。后来的一部编年史说，他曾告诫不要在温莎生产：蒙茅斯的亨利在位短而得之多，温莎的亨利在位长而失其全。不到一年父亲去世，婴儿成了英格兰和法国的国王。那句话应验了。",
  "house-of-lancaster:death": "1422年8月31日，亨利五世在万塞讷去世，年仅三十五岁。他的遗体被缓缓运过法国前往加来，棺上躺着一尊身着王袍的彩绘皮制雕像，每到一座城镇，四周都燃起火炬。在英格兰，人群沿着通往伦敦的道路肃立。11月7日他被安葬于威斯敏斯特教堂，他的头盔和马鞍悬挂在墓上方。",

  "celts:hunt": "约公元130年，希腊作家阿里安赞叹凯尔特人猎兔的方式：不用网，而是骑马跟在他们称为“vertragi”的快犬后面，只为追逐的乐趣。他记载，他们每猎杀一只兔、狐或鹿，就存下一枚钱币，每年一次用这笔积蓄为狩猎女神举行献祭和宴会，猎犬头上还戴着花冠。",
  "celts:battle": "公元前225年，在特拉蒙，高卢人被夹在两支罗马军队之间。波利比乌斯写道，盖萨泰（Gaesatae）战士站在最前排，除了金项圈和臂环外赤身裸体；无数号角和卡尼克斯号（carnyx）的轰鸣，加上全军的呐喊，仿佛是从大地本身发出。罗马人心生畏惧；然而高卢人还是被击溃了，他们的金项圈被运往卡比托利欧山。",
  "celts:gather": "在八月初、收获开始之际的卢纳萨节（Lughnasadh），爱尔兰的村社会登上山丘，采摘第一批越橘，割下第一捆麦，并举办竞技和说亲活动，以敬奉卢格神。后来基督徒把登山的习俗保留下来，称为“花环星期日”或“圣山星期日”，赤脚登上克罗帕特里克山（Cruach Phádraig）。初熟的果实是饥荒将尽、年景将好的征兆。",
  "celts:ritual": "早期爱尔兰文献记载了“公牛宴”（tarbfeis），用以得知谁当为塔拉（Teamhair）之王。人们宰杀一头白公牛，由一人饱食其肉、饮其汤，然后躺下，四位德鲁伊在他身旁吟诵。他在梦中看见的人便将为王；据说若他撒谎，他的嘴唇就会毁了他。未来就这样被郑重地、代表众人梦见。",
  "celts:rain": "想象：在苏格兰高地（a' Ghàidhealtachd）西部的一处海湾，一个氏族的船只被拖上卵石滩，准备划往群岛参加聚会。灰色的海雾笼罩水面，吞没了岬角。风笛手吹起一支舒缓的曲子来打发时间；老人们告诉年轻人，这根本算不上雨。到了中午，一阵山风把雾撕得四散。",
  "celts:flood": "亚里士多德和埃福罗斯都转述过一个关于北方海岸凯尔特人的故事：他们无所畏惧，当大潮漫上他们的土地时，他们拿起武器，列队走进海浪迎战，直到许多人溺死。希腊人称之为鲁莽。对凯尔特人来说，这或许是荣誉：不从任何东西面前逃跑，哪怕是大海。",
  "celts:wind": "约700年在艾奥那岛（Ì）写成的阿多姆南《圣科伦巴（Colm Cille）传》讲述：圣徒的修士们在群岛之间的科里夫雷坎漩涡（Coire Bhreacain）遭遇大风暴，远在艾奥那的科伦巴跪下为他们祈祷，他们因此获救。乘着蒙皮小艇（currach）出海的岛民与这样的风暴朝夕相伴，每次渡海都以祝福开始，以感恩结束。",
  "celts:fire": "约900年在爱尔兰写成的《科马克词汇》（Sanas Cormaic）说，在五月一日的贝尔丹节（Beltaine），德鲁伊念着咒语点燃两堆大火，把牛群从两火之间赶过，以保它们来年不染疫病。在苏格兰高地和爱尔兰，五月篝火的习俗一直延续到近代：家家熄灭炉火，再从圣火中重新引燃，夏季放牧随之开始。",
  "celts:thunder": "公元前335年，亚历山大大帝在多瑙河畔会见来自亚得里亚海沿岸的凯尔特使者。他问他们最怕什么，以为他们会说是他本人。他们回答说什么都不怕，只怕天塌下来砸在头上。他们的神塔拉尼斯手持车轮驾驭雷霆，唯有天穹崩裂，才能撼动这些本无所惧的人。",
  "celts:birth": "521年，科伦巴（Colm Cille）出生于多尼戈尔（Dún na nGall）的加坦。在他出生前，母亲艾特尼梦见一位天使给她带来一件五彩斗篷，斗篷随即升入空中，覆盖了爱尔兰和苏格兰的群山与湖泊。天使告诉她，她的儿子将引领无数灵魂升入天堂。这个贵族之子后来创建了艾奥那修道院，并把信仰带给了皮克特人。",
  "celts:death": "爱尔兰的守灵（tórramh）彻夜进行，有蜡烛、烟斗、故事和游戏；随后女人们唱起哀歌（caoineadh），那是悲恸与赞美交织的吟唱。1773年，艾布林·杜芙·尼·科奈尔（Eibhlín Dubh Ní Chonaill）发现丈夫阿特·奥利里（Art Ó Laoghaire）被枪杀，她为他唱的哀歌成为爱尔兰语最伟大的诗篇之一，满是爱、愤怒和她手上的鲜血。",

  "franks:hunt": "法兰克国王提奥德贝尔特一世是克洛维（Chlodowig）的孙子，酷爱在森林中猎捕巨大的野兽。拜占庭史家阿加西阿斯说，548年，一头巨大的野牛——原牛——向他冲来；它撞断的一根树枝砸在国王身上，使他受伤，不久便死去。猎捕野牛和原牛是王室的特权，也是王室的风险。",
  "franks:battle": "732年10月，在图尔与普瓦捷附近，查理·马特（Karl）的法兰克军队排成密集的盾墙，迎战倭马亚总督阿卜杜·拉赫曼的骑兵。754年的一部莫扎拉布编年史说，北方人站得“像一堵冰墙”，岿然不动，用剑砍倒阿拉伯人。阿卜杜·拉赫曼阵亡；夜里他的军队向南撤退，查理从此被称为“铁锤”。",
  "franks:gather": "约800年，查理曼（Karolus Magnus）颁布了《庄园敕令》（Capitulare de villis），为王室庄园立下规矩。它命令每位管家妥善记账，干净地酿造葡萄酒和啤酒，养蜂、修鱼塘，并种植开列的约九十种植物：百合、玫瑰、鼠尾草、芸香、黄瓜、苹果、梨。可以想象其背后管家的焦虑：在皇帝一家前来吃喝之前，一遍遍清点酒桶。",
  "franks:ritual": "图尔的格雷戈里记载，约555年，第戎（Divio）的神职人员想预知叛逆王子克拉姆恩的前途。他们把三本书——先知书、使徒书信和福音书——放在祭坛上，祈求上帝显明将要发生的事，然后随手翻开每一本。三段经文都预示着毁灭。他们没有说错：560年，克拉姆恩和家人被他自己的父亲烧死。",
  "franks:rain": "每年春天，在耶稣升天节前的祈祷日（Rogationes），法兰克的神职人员和村民跟在十字架后面绕行田界，吟唱连祷文，祈求上帝赐予好天气，结束霜冻与干旱。这一习俗源自维埃纳，470年代那里遭遇地震和火灾之后，主教马梅尔图斯首创了它。然后他们回家，等待上天的回应。",
  "franks:flood": "图尔的格雷戈里写道，580年奥弗涅连降大雨十二天，河水决堤，淹没了田地、人畜；卢瓦尔河和阿列河冲走了房屋和收成。他把这列为那个忧惧之年的征兆之一，与地震、瘟疫和天上的怪光并列。在他看来，洪水既是灾难，也是警示。",
  "franks:wind": "想象：亚琛（Aquisgrani）的冬天，北风在新宫殿中呼啸，吹得宫廷礼拜堂的铅顶哐哐作响。宫廷学校的修士们在烛光下伏身于蜡板，仆人们用稻草堵住门缝。艾因哈德告诉我们，皇帝喜欢在温泉中游泳；今夜，蒸汽被狂风撕散，老人们谈起异教的风暴之神。",
  "franks:fire": "艾因哈德讲述，查理曼在美因茨（Mogontia）的莱茵河上建造了一座长五百步的大木桥，耗时十年才完工。813年，即皇帝去世的前一年，桥起了火，三个小时就烧到了水面，水面以上连一块木板都没剩下。他的宫廷后来把这记作他大限将至的征兆之一。",
  "franks:thunder": "在查理曼814年去世前的种种预兆中，艾因哈德列举了：闪电击中他在亚琛的教堂屋顶上的金苹果，把它抛到了旁边主教的住所上。日食和地震震动宫殿，刻有查理为建造者之名的铭文逐渐褪色，几乎无法辨认。艾因哈德说，皇帝本人对这一切都置之不理。",
  "franks:birth": "图尔的格雷戈里记载，信基督教的王后克洛蒂尔德（Chrodechildis）为她与异教徒国王克洛维所生的长子施洗；婴儿穿着白袍死去。克洛维归咎于她的上帝。第二个儿子克洛多梅尔出生后，她也为他施洗，他随即病倒。她祈祷，孩子活了下来。国王看在眼里。不久之后，约496年，克洛维本人在兰斯（Remi）受洗。",
  "franks:death": "1653年，工人们在图尔奈（Tornacum）挖出了克洛维之父希尔德里克一世（Childerich）的墓，他约于481年去世。他身边有佩剑、一枚刻着他长发形象的金印戒、一件缝有约三百只金蜜蜂的斗篷和一个马头；后来的发掘又在他周围发现了整匹埋葬的马。他的人民以战士之礼把国王送往另一个世界，一应所需俱全。",

  "french:hunt": "1789年7月14日，巴士底狱陷落的那一天，路易十六在日记里写下一个词：“无”（Rien）。他指的是那天打猎一无所获。狩猎是他的激情和慰藉；多年来他记下了每一头鹿和野猪。这个词成了一位看不见自己世界正在终结的国王的象征，但它也显出一个热爱凡尔赛森林的腼腆之人。",
  "french:battle": "1792年9月20日，新生的法兰西共和国（République française）衣衫褴褛的军队在瓦尔米迎战普鲁士人。炮击持续了数小时；法军没有溃散，克勒曼将军把帽子挑在剑尖上高呼“民族万岁！”（Vive la Nation!）普鲁士人撤退了。在普军一侧观战的歌德对军官们说：从此地、从今日起，世界史开始了一个新纪元。",
  "french:gather": "法国的法律和习俗长期赋予穷人拾穗权（glanage）：收获运走之后，他们可以走进留茬的田里，捡拾收割者遗落的麦穗。1857年，让-弗朗索瓦·米勒画下了沙伊田间弯腰的三个女人，远处堆着富足的收成。巴黎的评论家认为这幅画很危险；而那些女人自己只盼着够过冬的面包。",
  "french:ritual": "1555年，米歇尔·德·诺查丹玛斯出版了他的第一部《预言集》，王后凯瑟琳·德·美第奇召他入宫，为她的孩子们占星。1559年亨利二世在比武中被长枪碎片刺伤而死时，人们认为其中一首四行诗早已预言了此事。天主教会反对算命，但忧心忡忡的王后和许多法国读者仍不停地追问未来。",
  "french:rain": "每当干旱或连绵阴雨威胁收成，巴黎人便请出城市主保圣女热纳维耶芙的圣髑盒。从中世纪到18世纪，这样的盛大游行有过许多次记载：圣髑盒从她的修道院抬下，与圣马塞尔的圣龛一起送往巴黎圣母院，赤脚的修士和全城行会都跟随其后。然后全城祈祷着，等待天气转变。",
  "french:flood": "1910年1月，塞纳河连涨数日，水位高出常时八米多。水灌满了地铁和地窖，巴黎人踩着木板、划着小船穿过街道。人们盯着阿尔玛桥上那尊朱阿夫士兵石像：水一直淹到他的肩膀。城市并没有惊慌；咖啡馆照常营业，邻里互相接济，直到河水退去。",
  "french:wind": "1999年12月26日和27日，两场大风暴“洛塔尔”和“马丁”以超过每小时170公里的风速横扫法国。数百万人在圣诞节期间断电，约九十人死亡。凡尔赛宫的园林里倒下了约一万棵树，其中包括玛丽-安托瓦内特时代种下的树。此后世界各地的人们纷纷捐款重植花园，仿佛在悼念老友。",
  "french:fire": "2019年4月15日傍晚，巴黎圣母院的屋顶起火。人群聚集在塞纳河畔，看着尖塔在火焰中坍塌。许多人跪下，在夜色中唱起《圣母经》（Je vous salue Marie）。消防员保住了钟楼和圣物。五年后，2024年12月7日，大教堂重新开放，钟声再次在巴黎上空响起。",
  "french:thunder": "1752年5月10日，在马尔利拉维尔，托马-弗朗索瓦·达利巴尔按照本杰明·富兰克林的设想，在雷雨中竖起一根高高的铁杆。留下看守的一名老兵看见火花噼啪地从铁杆上跳出，连忙跑去叫村里的神父。这是闪电即电的第一个证明。雷声，这上天之音，变成了法国人可以研究的东西。",
  "french:birth": "路易十三与奥地利的安妮结婚二十三年仍无存活的子嗣，直到1638年9月5日，一个儿子在圣日耳曼昂莱降生。全国钟声齐鸣，称他为“天赐的路易”（Louis Dieudonné）。没有人知道，这个男孩路易十四将统治七十二年，建造凡尔赛，使法国既荣耀辉煌又精疲力竭。",
  "french:death": "1840年12月15日，从圣赫勒拿岛（Sainte-Hélène）迎回的拿破仑遗骸被护送穿过巴黎，送往荣军院。天寒地冻，大雪纷飞，但数十万人仍列队站在香榭丽舍大街两旁。大军团的老兵们穿着褪色的军装落泪。他曾要求安息“在塞纳河畔，在我深爱的法国人民之中”。",

  "jeanne-darc:hunt": "1429年6月18日，奥尔良之战后，贞德的军队在帕泰附近搜寻撤退的英军。英格兰长弓手藏在树篱后面。这时一头雄鹿从林中窜出，径直冲进他们的阵线，弓箭手们发出了狩猎的呼喊。法国斥候听到了，骑兵趁木桩尚未打好便发起冲锋，英军全军覆没。人们说，是上帝派来了那头鹿。",
  "jeanne-darc:battle": "1429年5月7日，法军猛攻图雷尔堡——英军守卫奥尔良大桥的堡垒。贞德在架设云梯时被一箭射中胸口上方，含泪被抬下。她让人拔出箭，祈祷后又举着旗帜回来。士兵们看见旗帜触到城墙，便蜂拥而上，堡垒随之陷落。第二天早上，英军解除了围城。",
  "jeanne-darc:gather": "1431年在鲁昂受审时，法官问贞德是否学过一门手艺。她说学过：她跟母亲学会了缝纫和纺线，在这方面不怕鲁昂的任何女人。在栋雷米，她帮着料理家务，把牲畜赶去放牧，收获时下田干活。她为战争舍弃的，是一种朴素的乡村生活。",
  "jeanne-darc:ritual": "贞德告诉法官，她大约十三岁时，一个夏日正午，在栋雷米父亲的园子里，从教堂那一边听到来自上帝的声音，伴着一道强光。后来圣米迦勒（saint Michel）、圣凯瑟琳（sainte Catherine）和圣玛格丽特（sainte Marguerite）对她说话，常常是在钟声响起时。他们告诉她必须去开创的未来：解奥尔良之围，看着王太子加冕。",
  "jeanne-darc:rain": "1429年4月29日贞德抵达奥尔良时，运送补给的船只无法逆流而上：风向正与它们相反。指挥官迪努瓦后来作证说，她叫他等一等，突然之间，仿佛应她之言，风向变了，船只满帆驶过了英军的堡垒。他说，从那一刻起，他对她有了信心。",
  "jeanne-darc:flood": "想象：栋雷米的春天，冰雪消融后，默兹河漫过了草地。村里的孩子们被拦着不许靠近水边，男人们蹚水把羊群赶到舍努树林附近的高地上。贞德，一个混在其中的姑娘，帮着抱小羊。傍晚，村民聚集在小小的圣雷米（Saint-Rémy）教堂里，感谢上帝让洪水止于屋前。",
  "jeanne-darc:wind": "想象：1430年冬，贞德被关在博勒沃城堡的塔楼里，是勃艮第人的俘虏，等着被卖给英格兰人。暴风雨拍打着城墙，风从百叶窗缝里呼啸而入。她听说她答应援救的贡比涅仍被围困。她对等待绝望了，从塔上一跃而下——却活了下来，令所有人震惊。",
  "jeanne-darc:fire": "1431年5月30日，贞德在鲁昂老市场（Vieux-Marché）被处以火刑。她要一个十字架；一名英国士兵把两根木棍绑在一起递给她，一位神父从教堂举来苦像，让她能隔着浓烟看见。她一遍又一遍地呼唤耶稣的名字。目击者说许多人落泪，一位英国书记官喊道：“我们烧死了一位圣人。”",
  "jeanne-darc:thunder": "想象：1429年7月，在前往兰斯的路上，一场夏日暴雨在军队上空炸开，雷声滚过香槟的麦田。那些骂了一辈子粗话的士兵望着圣女，都闭上了嘴，因为她禁止他们赌咒。贞德卷起旗帜，冒雨继续前行。傍晚，特鲁瓦上空放晴，士兵们说这是加冕的好兆头。",
  "jeanne-darc:birth": "贞德约1412年出生于洛林边境的村庄栋雷米，父亲雅克·达克是农民，母亲是伊莎贝尔·罗梅。法国流传着一则据说出自梅林的古老预言：一位少女将从洛林边地的橡树林中走出，拯救王国。她的父母无法想象那就是自己的女儿，后来还激烈反对她离家。",
  "jeanne-darc:death": "火刑之后，英格兰人下令把贞德的骨灰撒进塞纳河，不留下任何可供敬奉之物。1456年，应她年迈的母亲伊莎贝尔·罗梅的请求而启动的重审宣布原判无效。伊莎贝尔站在巴黎圣母院中，为女儿讨还公道。1920年，近五个世纪之后，贞德被封为圣人。",

  "knights-templar:hunt": "1129年获准的《圣殿骑士团会规》（Règle du Temple）禁止弟兄们用鹰或猎犬打猎，也不许在追猎时呼喊，因为这类娱乐属于俗世。它只开了一个例外：骑士可以猎狮，因为狮子“遍地游行，寻找可吞吃的人”，乃是上帝之敌。他们的狩猎本应是与邪恶作战，而非消遣。",
  "knights-templar:battle": "1187年7月4日，干渴得几近疯狂的耶路撒冷王国军队在哈丁角被萨拉丁围困。圣殿骑士一次又一次冲锋，但全军覆没，真十字架（Vera Crux）也被夺走。战后，萨拉丁处决了约两百名被俘的圣殿骑士和医院骑士。力主进军的大团长杰拉尔·德·里德福尔却得以幸免。",
  "knights-templar:gather": "圣殿骑士在东方的战事，靠的是欧洲成千上万座农庄供养。在埃塞克斯的克雷辛圣殿，他们的弟兄于13世纪建起两座巨大的木结构谷仓，至今仍在，用来储存小麦和大麦的收成。平信徒弟兄和雇来的收割者耕作田地；利润用船运往阿卡。对那里的农工来说，圣地是用一捆捆麦子供养的。",
  "knights-templar:ritual": "入会者在夜间的分会上、当着聚集的弟兄们被接纳。他会被问到是否负债、是否有妻、是否有病，并被告诫将彻底放弃自己的意志。他宣誓服从、守贞、安贫，领受饰有红十字的白色斗篷，弟兄们唱起第133篇诗篇（Ecce quam bonum）。上帝赐他怎样的未来，已不再由他过问。",
  "knights-templar:rain": "想象：1250年春，一艘载着圣殿骑士新兵的船停在马赛港，等待航行季节。船长每天早晨嗅一嗅空气，而每天早晨密史脱拉风都吹错了方向。年轻的骑士们在港边的圣殿礼拜堂祈祷，擦亮锁子甲。风终于转向时，他们画着十字启航前往阿卡，不知道自己再也回不来了。",
  "knights-templar:flood": "想象：冬天，朝圣者涉渡处的约旦河水浑黄湍急地上涨。誓言保护从耶路撒冷到河边路上行旅的圣殿骑士骑马下来，警告一群朝圣者不要渡河。朝圣者们哭了；他们远道而来，就是为了在基督受洗之处沐浴。骑士们在他们身旁扎营守望，直到河水退去，渡河安全。",
  "knights-templar:wind": "1291年5月，马穆鲁克攻入十字军最后一座大城阿卡。圣殿骑士在海边的要塞坚守多日，船只则把难民运走。风暴肆虐的大海使逃亡变得致命；妇女和儿童溺死在港口。5月28日，圣殿的城墙坍塌，守军与攻方同归于尽。骑士团的财宝随蒂鲍德·戈丹北航至西顿。",
  "knights-templar:fire": "1314年3月18日，圣殿骑士团最后一任大团长雅克·德·莫莱和若弗鲁瓦·德·沙尔奈在塞纳河中一座面对巴黎圣母院的小岛上被活活烧死。他们撤回了供词，宣称骑士团无罪。德·莫莱请求面朝大教堂被绑，双手空出以便祈祷。人群为他们的从容所动，有人收起他们的骨灰作为圣物。",
  "knights-templar:thunder": "想象：在加利利的萨费德城堡——圣殿骑士于1240年代重建——一场夜间雷暴在城墙上空炸开。弟兄们按会规起身做晨祷，在黑暗的礼拜堂中念诵天主经，闪电照亮了下方的山丘。谁也不得离开自己的位置，也不得说无谓的话。暴风雨过去后，守夜人报告道路平静。",
  "knights-templar:birth": "圣殿骑士是修士，不能有子女；会规甚至禁止他们当教父。他们自身的诞生是在1129年的特鲁瓦会议上：于格·德·帕英和几个保护朝圣者的贫穷骑士获得了会规，以及克莱尔沃的伯尔纳的支持。很少有人料到，这个小小的兄弟会将在整个基督教世界变得富有而强大。",
  "knights-templar:death": "圣殿骑士团会规规定了弟兄去世时该怎么做。七天之内，每位弟兄要为他的灵魂念一百遍天主经（Pater noster）；四十天之内，他的那份饮食要施给一个穷人。去世的弟兄穿着会衣，葬在他去世的会所。不作哀恸之态；一位圣殿骑士在弟兄们的祈祷中归于上帝。",

  "burgundians:hunt": "在阿图瓦的埃斯丹园林，勃艮第公爵们在围墙环绕的森林中猎鹿，还保留着一条满是机关的长廊来捉弄宾客：会喷水的雕像，会让访客掉进羽毛袋的活板地面，还有一台能制造雷声和雨的机器。好人腓力（Philippe le Bon）在1430年代修复了它。在那里打猎，结局是欢笑、湿衣服和一场盛宴。",
  "burgundians:battle": "1476年3月2日，大胆查理（Charles le Téméraire）的军队在格朗松与瑞士人相遇。瑞士主力翻过山丘时，乌里和翁特瓦尔登的巨大号角——人称“公牛”和“母牛”——在山谷中轰鸣。勃艮第人惊慌溃逃，丢下了公爵的帐篷、挂毯、黄金和钻石。瑞士人瓜分了财宝；公爵的骄傲再也没有恢复。",
  "burgundians:gather": "1395年，勇敢的腓力（Philippe le Hardi）公爵禁止在金丘种植“不忠”的佳美葡萄，下令只种黑皮诺，从而永远塑造了勃艮第葡萄酒。1443年，掌玺大臣尼古拉·罗兰在博讷创建主宫医院（Hôtel-Dieu）救济穷人，经费来自捐赠的葡萄园。收获时节，采摘者知道他们的葡萄将为病人换来面包和床铺。",
  "burgundians:ritual": "1454年2月17日，好人腓力在里尔举办了雉鸡宴（Banquet du Faisan）。君士坦丁堡陷落之后，一只饰满珠宝的活雉鸡被带进大厅，公爵和他的骑士们对着它立下十字军东征的宏大誓言，气氛一半是骑士游戏，一半是真诚的祈祷。他们向上帝询问基督教世界的未来。那支十字军始终没有出发。",
  "burgundians:rain": "想象：第戎的秋天，雨已经下了九天。科特山坡上的葡萄等着采收，一颗颗涨大、裂开。葡萄农聚集在圣母院教堂，在两场弥撒之间仰望天空。终于，一阵北风从高原吹下，吹干了山坡。不到一天，家家户户都在葡萄行间剪收。",
  "burgundians:flood": "想象：1446年，在勃艮第治下的低地国家，一场风暴潮冲垮了佛兰德和泽兰的堤坝。公爵的官员骑马出去清点被淹的村庄和损失的租税。在布鲁日，商人们看着运河水位上涨，担心仓库能否保住。洪水退去后，公爵减免了赋税，农民们又开始筑堤挡海。",
  "burgundians:wind": "想象：1468年6月，约克的玛格丽特从马盖特渡海前往斯勒伊斯，去嫁给大胆查理。一场夏日大风颠簸着船队，她的侍女们晕船又害怕。船只终于驶入兹温河口时，勃艮第宫廷已备好音乐和珠宝等候。随后在布鲁日连日欢宴，还有鲸鱼形状的彩车和一头独角兽。风暴成了餐桌上的谈资。",
  "burgundians:fire": "1468年，列日城反叛勃艮第公爵。大胆查理强攻破城，下令焚城。数周之内，他的士兵一条街接一条街地放火，只放过了教堂；市民被两两绑在一起投入默兹河溺死。被迫在旁观看的法王路易十一一言不发。这座骄傲的城市世世代代记着这场焚烧。",
  "burgundians:thunder": "想象：1475年夏，莱茵河畔的诺伊斯围城战中，一场雷暴在勃艮第军营上空炸开。闪电击中公爵帐篷附近，士兵们跪倒在泥里。围城已持续将近一年。有人说上帝站在公爵的对立面；大胆查理下令向暴风雨开炮还击。几周后，他放弃了围城。",
  "burgundians:birth": "1457年2月13日，波旁的伊莎贝尔在布鲁塞尔生下一个女儿。她的丈夫、未来的大胆查理原本盼望儿子；此后再无子女。二十年后，查理战死于南锡，这个女孩——勃艮第的玛丽（Marie de Bourgogne）——继承了他的全部领地。她嫁给了奥地利的马克西米利安，她的孙子成为皇帝查理五世。",
  "burgundians:death": "为1404年去世的勇敢的腓力修建陵墓时，克劳斯·斯吕特及其后继者雕刻了四十个小小的大理石哀悼者（pleurants），在公爵卧像下排成送葬行列，面容藏在兜帽里，每个人悲伤的样子都不相同。它们展示了勃艮第宫廷如何安葬公爵：无尽的黑衣队列、圣咏、烛火，以及化为艺术的哀恸。如今它们仍在第戎行进着。",

  "dutch:hunt": "从1619年起，荷兰捕鲸人每年夏天都在斯匹次卑尔根外一座岛上的斯梅伦堡（“鲸脂镇”）度过。人们划着敞篷小艇追捕格陵兰露脊鲸，用鱼叉刺中它，拖上岸，在巨大的铜锅里熬炼鲸脂。数百人在午夜阳光下的浓烟和恶臭中劳作。许多人死于寒冷和坏血病，他们的坟墓至今仍留在北极海岸上。",
  "dutch:battle": "1667年6月，第二次英荷战争期间，米希尔·德·勒伊特的舰队驶入梅德韦河，冲断了查塔姆河面上的拦河铁链，烧毁了停泊的英国战舰。他们把旗舰“皇家查理号”作为战利品拖回国；它雕花的船尾至今仍在荷兰国家博物馆。在伦敦，塞缪尔·佩皮斯担心末日来临；在共和国，钟声连响数日。",
  "dutch:gather": "1612年，阿姆斯特丹以北的贝姆斯特湖被四十三座风车抽干，湖底被规划成田地、道路和沟渠组成的完美网格。投资的商人们看着曾经是水的土地上长出了第一批小麦、养起了第一批牛。对荷兰人来说，在圩田上收获是一个朴素的奇迹：靠自己双手造出的土地，蒙上帝赐福。",
  "dutch:ritual": "荷兰加尔文派不靠星象或纸牌来预知未来；他们祈祷。三月第二个星期三是“作物与劳作祈祷日”（Biddag voor Gewas en Arbeid），归正会教堂里的农民和渔民祈求上帝赐福即将到来的季节。在“圣经带”的村庄里，这一天至今仍被遵守，学校放假，教堂坐满，庄严而充满希望。",
  "dutch:rain": "1688年10月，奥兰治的威廉（Willem van Oranje）的入侵舰队在海勒富茨勒伊斯等待东风送他们去英格兰。第一次尝试被风暴逼回。11月11日风转向东——“新教之风”——它把荷兰船只送下海峡，同时把英国舰队困在泰晤士河里。荷兰牧师们祈求的正是这个。",
  "dutch:flood": "1421年11月18日至19日夜，圣伊丽莎白洪水（Sint-Elisabethsvloed）冲垮了荷兰大瓦尔德的堤坝。约二十个村庄消失了；那片土地变成了比斯博斯沼泽。传说风暴过后，一只木摇篮漂上岸，里面睡着一个婴儿，一只猫左右跳动使摇篮保持平衡。那个地方后来叫作小孩堤防（Kinderdijk）。",
  "dutch:wind": "1953年1月31日夜，一场西北风暴把北海推向泽兰和南荷兰。涨潮时，堤坝在数十处决口；1836人溺亡，许多人死在床上。幸存者在屋顶上等了好几天。荷兰人称之为“大洪灾”（Watersnoodramp），并以三角洲工程作答，誓言风和海再也不能那样夺走他们。",
  "dutch:fire": "1652年7月7日，阿姆斯特丹的旧市政厅（stadhuis）被烧毁。围观的人群中有年轻的扬·范德海登，他永远忘不了那些无能为力的传桶队伍。1672年，他和兄弟发明了带柔性皮水管的消防车，阿姆斯特丹的火灾从此远没有那么致命。后来他以清晰而宁静的笔触画下了新市政厅，仿佛要确保它永存。",
  "dutch:thunder": "1654年10月12日，代尔夫特一座火药库爆炸，轰鸣声远在特塞尔岛都能听到。约四十吨火药夷平了城市的四分之一，炸死一百多人，其中包括正在画室里的《金翅雀》作者卡雷尔·法布里蒂乌斯。“代尔夫特霹雳”（Delftse Donderslag）被视为上帝的警告；城市重建起来，维米尔画下了它宁静的街道。",
  "dutch:birth": "1650年11月14日，父亲威廉二世死于天花八天之后，玛丽·斯图亚特在海牙（Den Haag）生下一个儿子。荷兰省的执政者们乐于摆脱奥兰治家族的执政，多年不让这个婴儿掌权。许多荷兰人却仍寄望于他。1672年“灾难之年”（Rampjaar），他拯救了共和国；1689年，他成为英格兰的威廉三世（Willem III）。",
  "dutch:death": "海军上将米希尔·德·勒伊特1676年在西西里外海受了致命伤。他经过防腐处理的遗体被运回国，1677年3月18日在阿姆斯特丹新教堂举行隆重的公祭后安葬。成千上万人站满了街道和运河两岸。共和国为他建造了大理石陵墓，但朴素的荷兰牧师提醒哀悼者：他曾是一个谦卑、常常祈祷的人。",

  "spanish:hunt": "腓力四世（Felipe IV）酷爱狩猎，委拉斯开兹为马德里附近的托雷德拉帕拉达狩猎行宫画了他：身着朴素的棕色猎装，带着猎枪和猎犬。王家狩猎在用帆布围成的大围场（tela）中进行，鹿和野猪被驱赶着从国王和廷臣面前跑过。大狩猎（montería）既是排场也是政治；驱兽人只盼着国王枪法准一些。",
  "spanish:battle": "1571年10月7日，奥地利的唐·胡安（Don Juan de Austria）率领神圣同盟舰队在勒班陀与奥斯曼舰队交战。年轻的士兵米格尔·德·塞万提斯正发着高烧，却坚持参战；他胸部中了两枪，左手从此残废。他后来称之为“过去和现在的世代所见过的最崇高的时刻”，并终生以此为荣。",
  "spanish:gather": "每年冬天，哈恩的橄榄采摘工（aceituneros）在树下铺开网，用长杆敲打树枝，把橄榄收集起来送往油坊。他们是没有土地的短工，树归大庄园所有。1937年，诗人米格尔·埃尔南德斯写下《橄榄采摘工》，问哈恩骄傲的安达卢西亚人：是谁栽种了这些橄榄树？它后来成了这个省的颂歌。",
  "spanish:ritual": "1588年，无敌舰队驶向英格兰之际，腓力二世（Felipe II）下令西班牙所有教堂举行祈祷；在埃斯科里亚尔，修士们日夜轮班在圣体前祈祷。国王本人也一跪就是几个小时，祈求上帝赐予胜利。据说当惨败的消息传来时，他平静地答道：他派船去是和人作战，不是和风作战。",
  "spanish:rain": "在卡斯蒂利亚和安达卢西亚干燥的腹地，干旱持续太久时，城镇会举行祈雨游行（rogativas pro pluvia）：抬着主保圣人或圣母像穿过田野，祈求降雨。有些圣像被请出圣所，不下雨就不送回。农民们默默跟在后面，仰望着苍白的天空，等待世界改变。",
  "spanish:flood": "1957年10月14日，连日大雨使图里亚河奔涌着冲过瓦伦西亚。老城附近的街道上水深超过五米；至少八十人死亡。邻居们躲到楼上和屋顶上。城市决定再也不让河水穿城而过：河道被改向南方，旧河床变成了图里亚花园，一条贯穿瓦伦西亚的长长绿色公园。",
  "spanish:wind": "1588年9月，在海峡战败后，无敌舰队的船只绕过苏格兰和爱尔兰返航。大西洋风暴把约二十多艘船抛上了爱尔兰海岸。在斯莱戈郡斯特里达失事的弗朗西斯科·德·奎利亚尔船长幸存下来，他写到自己如何从上千具尸体中爬上岸，又如何被爱尔兰首领们藏匿，最终辗转回到西班牙。",
  "spanish:fire": "1734年平安夜，马德里的旧阿尔卡萨宫起火，大火烧了四天。仆人和修士们砸破窗户，把画作扔到雪地里抢救；委拉斯开兹的《宫娥》就在被救出的画作之中，但约有五百件作品被毁。腓力五世（Felipe V）在原址上建起了全石结构的新王宫（Palacio Real），让它再也不会被烧毁。",
  "spanish:thunder": "想象：1640年夏，一场雷暴在拉曼查平原上空炸开。在坎波德克里普塔纳村，磨坊主锁住风车的叶片，教堂按照习俗敲钟对抗风暴，以驱散冰雹。农民们跪在葡萄藤间。冰雹放过了他们的葡萄，他们便聚到教堂，向村里的基督像谢恩。",
  "spanish:birth": "1661年11月6日，就在国王长子夭折几天之后，王后玛丽安娜在马德里生下一个儿子。这个孩子卡洛斯体弱多病，是王室世代近亲通婚的结果。全西班牙都祈祷他能活下来并留下继承人。他确实以卡洛斯二世之名在位三十五年，人称“中魔者”（el Hechizado），但死后无嗣，欧洲为他的王位打了一场战争。",
  "spanish:death": "西班牙国王安葬在埃斯科里亚尔主祭坛下的国王陵（Panteón de los Reyes），那是腓力二世时期建造的。但遗体要先在一间密封的“腐化室”（pudridero）中存放数十年，直到只剩白骨，然后才被安放进大理石骨灰瓮。这是西班牙天主教信仰中一种严峻而耐心的习俗：在死亡中谦卑，等待漫长的末日审判。",

  "portuguese:hunt": "从18世纪直到1987年，亚速尔群岛（Açores）的男人们驾着敞篷木船，用手掷鱼叉捕猎抹香鲸。山上的瞭望员一看到鲸鱼喷水就放出信号火箭，皮库岛拉日什的男人们便丢下田地和店铺，跑向船只。这是危险又清贫的营生，下水前要向圣人祈祷。如今，旧日的瞭望台为游客观鲸。",
  "portuguese:battle": "1385年8月14日，在阿勒茹巴罗塔，国王若昂一世和统帅努诺·阿尔瓦雷斯·佩雷拉率领的一支小小的葡萄牙军队，击败了前来争夺王位的规模大得多的卡斯蒂利亚军队。葡萄牙人挖了壕沟和陷坑，英格兰弓箭手也助了一臂之力。传说面包师妇人布里特斯·德·阿尔梅达用面包铲打死了七个逃跑的卡斯蒂利亚人。葡萄牙保住了独立。",
  "portuguese:gather": "在杜罗河谷，酿造波特酒的葡萄由男人们排成单行，用沉重的筐子背下陡峭的梯田。夜里，葡萄在石砌的踩池（lagar）中被赤脚踩踏，踩踏者手挽着手，随着手风琴、鼓和工头的号子有节奏地踏步。累了，他们就唱歌。这是艰苦的劳作，也是庆祝一整年辛劳的节日。",
  "portuguese:ritual": "1497年7月7日夜，瓦斯科·达·伽马和他的船员们在塔霍河（Tejo）边雷斯特洛的小礼拜堂里守夜，为前往印度的航行祈祷。第二天早上，他们手持蜡烛列队走向船只，神父吟唱，人群哭泣，许多人以为再也见不到他们了。两年后，回来的不到一半。",
  "portuguese:rain": "1578年8月4日，国王塞巴斯蒂昂在摩洛哥的阿尔卡塞尔-基比尔（Alcácer-Quibir）战役中失踪，遗体始终未能确认。葡萄牙不久便落入西班牙统治之下。数百年来，许多葡萄牙人相信他会在一个雾蒙蒙的早晨归来拯救祖国。塞巴斯蒂昂主义成了一种思念（saudade）与希望交织的情感：等待雾散，等待隐匿的国王策马而出。",
  "portuguese:flood": "1755年11月1日万圣节，晨间弥撒时，一场大地震袭击了里斯本（Lisboa）。幸存者跑到海滨的空地上，却看见海水退去，露出河床，随后海啸漫过码头和商业广场。数千人溺亡。整个欧洲都在问，上帝怎么会容许这样的事，伏尔泰写下了一首愤怒的诗。",
  "portuguese:wind": "1488年，巴尔托洛梅乌·迪亚士被一场持续十三天的风暴吹到了遥远的南方。风暴结束后，他向东航行，发现自己已经绕过了非洲的南端。回程途中，他看见了那个海角，命名为风暴角（Cabo das Tormentas）。国王若昂二世将它改名为好望角（Cabo da Boa Esperança），因为它打开了通往印度的海路。是风暴指明了道路。",
  "portuguese:fire": "1755年的地震发生在万圣节，教堂里点满了蜡烛。蜡烛倾倒，大火在里斯本燃烧了五六天，吞噬了宫殿、图书馆和王家歌剧院。据说有人问该怎么办时，庞巴尔侯爵回答：“埋葬死者，养活生者。”他把下城（Baixa）重建成笔直的街道。",
  "portuguese:thunder": "在卡蒙斯1572年的史诗《卢济塔尼亚人之歌》（Os Lusíadas）中，当达·伽马的船队接近好望角时，一片乌云升起，大海咆哮，巨人阿达马斯托尔——海角之灵——现身了。他以雷鸣般的声音预言葡萄牙人在这条航线上将遭遇的海难与死亡。水手们惊恐地听着，却继续航行。许多读者从中听到了自己的历史。",
  "portuguese:birth": "1394年3月4日，在波尔图，兰开斯特的菲利帕（Filipa de Lencastre）生下了她的第三个儿子恩里克。那时国家刚刚独立，前途未卜。没有人知道这位王子将以“航海家亨利”（Infante Dom Henrique）之名被铭记，他资助的沿非洲海岸南下的航行改变了世界，有福也有祸。据说他的母亲临终前给每个儿子都赐了一把剑。",
  "portuguese:death": "佩德罗王子的爱人伊内斯·德·卡斯特罗于1355年奉他父亲之命被杀。传说佩德罗即位后，命人掘出她的遗体，为她加冕，让她坐上王座，并令满朝廷臣亲吻她的手。他们在阿尔科巴萨修道院的石棺彼此相对，好让他们在末日复活时，第一眼看见的便是对方。",

  "italians:hunt": "佛罗伦萨（Firenze）的统治者洛伦佐·德·美第奇约在1470年写了一首诗《猎鹧鸪》（L'uccellagione di starne），讲述他和朋友们在托斯卡纳山间放鹰猎鹧鸪的一个早晨。诗中满是隼和猎犬的名字、谁的鹰飞得最好的争吵、一只走失的鹰，以及饥肠辘辘赶回去吃饭的归途。对佛罗伦萨的精英来说，狩猎就是友谊、诗歌和乡野之乐的合一。",
  "italians:battle": "1176年5月29日，伦巴第联盟（Lega Lombarda）诸城在莱尼亚诺迎战皇帝腓特烈·巴巴罗萨。市民步兵聚集在战车（Carroccio）周围——那是一辆载着城市旗帜和祭坛的大牛车——发誓誓死捍卫。他们守住了，米兰骑兵回援，皇帝坠马，一度被认为已死。意大利的自由城市赢得了它们的自由。",
  "italians:gather": "1338年，安布罗焦·洛伦泽蒂在锡耶纳市政厅的墙上画下了《好政府的效果》（Effetti del Buon Governo）。在城门外的乡间，农民们割麦、打谷，赶着驮满麻袋的骡子进城，还有人放鹰打猎，一个有翼的“安全”之神俯瞰着这一切。九人议会希望市民记住：和平带来丰收。十年后，瘟疫来了。",
  "italians:ritual": "教宗去世后，枢机们被关进秘密会议选举继任者，向圣灵祈祷。外面，圣彼得广场（Piazza San Pietro）上的人群盯着西斯廷礼拜堂（Cappella Sistina）上的一根小烟囱。黑烟表示尚未决定；白烟和钟声则意味着新教宗诞生。人们等待着，许多人在祈祷，不知道谁将在未来的岁月里领导教会。",
  "italians:rain": "想象：十一月的波河平原（Pianura Padana），曼托瓦（Mantova）的雾浓得船夫们不肯把驳船驶上湖面。等着把奶酪和大米顺流运往威尼斯的商人们坐在酒馆里抱怨。店主说，雾（nebbia）想散的时候自然会散。第三天早上，太阳穿透了雾，河面上忽然挤满了帆。",
  "italians:flood": "1966年11月4日，阿诺河在佛罗伦萨（Firenze）决堤。深达六米的水和泥浆灌满了圣十字教堂周围的街道，损毁了契马布埃的十字架像和数百万册书籍。来自意大利和世界各地的年轻志愿者赶来，用双手把图书馆和档案馆清理出来；佛罗伦萨人称他们为“泥浆天使”（angeli del fango）。",
  "italians:wind": "1343年11月25日，彼特拉克（Francesco Petrarca）身在那不勒斯（Napoli），一场大风暴袭击了海岸。他写信给朋友说，他看见海水漫过港口，船只互相撞毁，年轻的女王带着侍女赤脚走向教堂祈祷。他发誓只要能避免，就再也不走海路。他的信是欧洲最早的风暴目击记述之一。",
  "italians:fire": "1497年2月7日，佛罗伦萨的狂欢节，多明我会修士吉罗拉莫·萨伏那罗拉的追随者在领主广场上堆起一座巨大的金字塔，焚烧“虚荣之物”（falò delle vanità）：镜子、化妆品、纸牌、鲁特琴、书籍和画作。孩子们挨家挨户收来这些东西。许多佛罗伦萨人觉得自己得到了净化和拯救；另一些人则怒不可遏。十五个月后，萨伏那罗拉本人也在同一个广场被烧死。",
  "italians:thunder": "1492年4月5日夜，闪电击中佛罗伦萨大教堂（Santa Maria del Fiore）穹顶的灯笼亭，大理石块朝美第奇宫方向坠落。病重卧床于卡雷吉的洛伦佐·德·美第奇问掉在了哪一边，听到答案后说他要死了。三天后他去世。佛罗伦萨人把这道闪电看作随之而来的动荡的预兆。",
  "italians:birth": "1452年4月15日，公证人安东尼奥·达·芬奇在笔记本上写道，他的孙子于当夜三时出生，并列出了洗礼时的教父教母。这孩子是私生子，是公证人塞尔·皮耶罗与一个名叫卡泰丽娜的年轻女子所生，不能继承父亲的职业。他的名字叫列奥纳多。芬奇镇上没有人想象得到他将成为什么样的人。",
  "italians:death": "拉斐尔（Raffaello Sanzio）于1520年4月6日耶稣受难日在罗马（Roma）去世，那天正是他三十七岁生日。他未完成的《耶稣显圣容》被放在灵床头前，瓦萨里写道，所有在那里看到它的人都落了泪。他按自己的遗愿葬于万神殿。教宗利奥十世（papa Leone X）也哭了。罗马哀悼他，仿佛一位天使离去。",

  "sicilians:hunt": "西西里国王、皇帝腓特烈二世（Federico II）在1240年代写了论著《鸟猎之艺》（De arte venandi cum avibus）。他亲自研究隼，检验他在亚里士多德书中读到的观点，并记载他曾把秃鹫的眼睛封住，看它们是靠视觉还是嗅觉找到食物。在他看来，狩猎是一门科学，他爱他的鸟胜过廷臣们爱它们。",
  "sicilians:battle": "1282年3月30日复活节星期一的晚祷时分（Vespri siciliani），在巴勒莫（Palermu）圣灵教堂外，一名法国士兵侮辱了一个西西里女人，她的丈夫杀了他。人群起来反抗安茹的查理手下的法国统治者。随后几周，全西西里的法国人都遭到杀戮。传说凡是不能用西西里口音说出“ciciri”（鹰嘴豆）的人，都被当作法国人。",
  "sicilians:gather": "每年春天，在法维尼亚纳的金枪鱼渔场（tonnara），渔民们布下迷宫般的网阵，围捕洄游经过的蓝鳍金枪鱼。当最后一间网室里的鱼够多时，首领（rais）一声令下，男人们唱着号子（cialoma）把网拉起，在“屠戮”（mattanza）中用钩子钩住巨大的鱼。这是艰苦、血腥而古老的劳作，是全岛从大海获得的收成。",
  "sicilians:ritual": "1624年巴勒莫闹瘟疫时，一个女人梦见圣罗莎莉亚（Santa Rusulia）指给她看自己的遗骨在佩莱格里诺山的一个洞穴里。人们找到了遗骨，抬着它在城中游行，瘟疫随即结束。此后每年七月，巴勒莫都举办圣罗莎莉亚节（Festino），拉着她巨大的彩车穿过街道，祈求她保佑城市来年平安。",
  "sicilians:rain": "西西里人说，中世纪时一场可怕的干旱袭击了全岛，人们向圣约瑟（San Giuseppi）祈雨，许诺若是下雨就敬奉他。雨下了，人们为表感谢，摆出食物款待穷人。此后每年3月19日，家家户户都布置“圣约瑟之桌”（Tavola di San Giuseppe），一座摆满面包、蚕豆和甜点的祭台，招待每一个上门的人。",
  "sicilians:flood": "1908年12月28日黎明，一场大地震袭击了墨西拿海峡（Strittu di Missina），几分钟后，高达十二米的海啸席卷了墨西拿和雷焦的海滨。约有八万人遇难。停泊在附近的俄国海军水兵是最早挖掘幸存者的人之一。墨西拿用低矮的房屋重建起来，从未忘记这场灾难。",
  "sicilians:wind": "想象：在利帕里岛，一个渔夫的妻子看着海面在密史脱拉风下翻起白浪。丈夫的船还在海上。女人们聚到圣母领报教堂，向岛的主保圣人圣巴尔多禄茂（San Bartulumeu）祈祷。傍晚时分，海上亮起一盏灯，接着出现了船身。她跑下港口，一路上数落着他，又哭又笑。",
  "sicilians:fire": "1669年3月，埃特纳火山（Mungibeddu）喷发，一条熔岩河流向卡塔尼亚。迭戈·帕帕拉尔多带领五十个披着湿牛皮的人去凿开凝固的外壳，使熔岩改道。熔岩转向了帕泰尔诺镇，那里的武装民众把他们赶走了。熔岩最终抵达卡塔尼亚城墙，涌入大海。西西里人不停地向圣阿加莎（Sant'Àita）祈祷，人们举着她的面纱去抵挡火焰。",
  "sicilians:thunder": "1693年1月11日，一场大地震袭击了西西里东南部的诺托谷，幸存者把那轰鸣比作来自地下的雷声。约六万人死亡，卡塔尼亚、诺托、拉古萨和莫迪卡沦为废墟。西西里人以一种崭新而欢快的巴洛克风格重建了它们——金色的石头，弯曲的阳台——仿佛要用美来回应死亡。",
  "sicilians:birth": "西西里诺曼王朝的继承人奥特维尔的康斯坦丝（Costanza d'Altavilla）与皇帝亨利六世结婚九年无子，四十岁时终于怀孕。她担心有人怀疑，便于1194年12月26日在耶西公共广场的一座帐篷里分娩，让城里的妇女们作证。这个孩子腓特烈在巴勒莫作为孤儿长大，后来成为被称为“世界奇迹”的皇帝。",
  "sicilians:death": "巴勒莫嘉布遣会修道院之下是地下墓穴（Catacombe dei Cappuccini）。从1599年起，先是修士，后来是贵族和商人，在这里被风干保存，穿上最好的衣服，沿墙排成长列。家人前来探望、祈祷，再为他们换衣。最后一位是罗莎莉亚·隆巴尔多，一个1920年去世的两岁小女孩，至今看上去仍像在熟睡。",

  "maltese:hunt": "1530年，皇帝查理五世把马耳他授予圣约翰骑士团（il-Kavallieri ta' San Ġwann），每年的贡赋只是一只隼，于万灵节送交西西里总督。每年都有一只训练有素的鸟离开马耳他，这是骑士团为这座岛支付的唯一租金。春秋两季飞越上空的隼、鹌鹑和斑鸠，向来是马耳他人猎捕的对象。",
  "maltese:battle": "1565年5月至9月，奥斯曼军队围攻马耳他。圣艾尔摩堡（Forti Sant'Iermu）坚守了一个月，于6月23日陷落；守军全部战死。但由大团长让·德·瓦莱特率领骑士和马耳他人防守的比尔古和森格莱阿（l-Isla）始终未被攻破。9月8日，土耳其人撤退。马耳他人至今仍以“胜利日”（Il-Vittorja）庆祝这一天。",
  "maltese:gather": "在戈佐岛（Għawdex）的谢伊尼海岸，凿在石灰岩上的盐田已经被经营了数百年。炎热的夏季，一家家人把海水引入盐田，让太阳晒干；然后把白盐扫成堆，装进麻袋扛走。这是安静而累断腰的活计，祖父母和孙辈用同样的方式，在同一个太阳下劳作。",
  "maltese:ritual": "1883年，戈佐岛加尔卜村的妇女卡尔姆尼·格里马经过塔皮努小礼拜堂时，听到一个女人的声音在呼唤她。她进去祈祷，那声音让她念三遍圣母经（tliet Sliema għalik Marija）。后来，她自己的母亲在她的祈祷之后痊愈了。从此朝圣者纷纷来到塔皮努，向圣母询问自己的未来，并为得到应允的祈祷留下谢意。",
  "maltese:rain": "想象：18世纪一个干旱的春天，马耳他乡间的农民看着半空的蓄水池和满是石头的梯田。他们抬着主保圣人（il-qaddis patrun）的雕像列队走向教区教堂，祈求降雨。一连几天，天空湛蓝无云。然后，一片灰色的天空从西南方升起，第一批沉重的雨点落在温热的石头上，转眼就干了。",
  "maltese:flood": "想象：一场秋季暴雨降在马耳他，激流冲下贯穿全岛的狭窄山谷（widien）。在比尔基卡拉和戈尔米，街道变成了河流，水把大车和门板冲向港口。邻居们互相拉上平屋顶，等待着。水退之后，他们扫出淤泥，说马耳他下雨只是为了补上夏天欠的。",
  "maltese:wind": "据《使徒行传》记载，约公元60年，一艘押送圣保罗（San Pawl）去罗马的船被猛烈的东北风裹挟了十四天，在马耳他触礁失事。路加写道：“土人看待我们有非常的情分，因为当时下雨，天气又冷，就生火接待我们众人。”马耳他人在2月10日纪念保罗的船难，视之为他们信仰的到来。",
  "maltese:fire": "1942年春，马耳他是世界上遭受轰炸最多的地方。4月7日，德国炸弹摧毁了瓦莱塔（il-Belt Valletta）的皇家歌剧院；城市废墟中大火燃烧。人们睡在岩石防空洞里，排队领取食物。4月15日，国王乔治六世授予全岛乔治十字勋章，表彰其勇气。歌剧院的废墟矗立了数十年，作为一种提醒。",
  "maltese:thunder": "1942年4月9日空袭中，一枚德国炸弹穿透了莫斯塔圆顶教堂（ir-Rotunda tal-Mosta）的穹顶，当时约有三百人聚集在里面做晚祷。炸弹在地面上弹跳滚过，没有爆炸。无人受伤。莫斯塔的人们称之为圣母的奇迹，炸弹的复制品至今仍保存在教堂里。",
  "maltese:birth": "马耳他孩子满一周岁时，家人会举行“抓周”（quċċija）。婴儿坐在地上，四周摆着各种物件：念珠、笔、书、硬币、煮鸡蛋、剪刀。据说孩子最先抓起的东西会显示他的未来：神父、作家、富人。全家欢笑喝彩，但每个人心里也在悄悄猜想，这孩子会过上怎样的一生。",
  "maltese:death": "骑士团大团长、大围攻（l-Assedju l-Kbir）的英雄让·德·瓦莱特，于1568年8月21日在打猎时中风后去世。他的遗体由桨帆船载着渡过港湾，送往以他名字命名的新城瓦莱塔，安葬在一座礼拜堂里，后来迁入圣约翰副主教座堂（il-Konkatidral ta' San Ġwann）的墓室。马耳他人和骑士们把他当作全岛的救主来哀悼。",

  "britons:siege": "1461年至1468年，达维兹·阿布·伊安·阿布·艾宁率领一支小小的守军，坚守着海边岩石上的哈勒赫城堡（Castell Harlech），那是他们一方在漫长内战中的最后据点。补给偶尔从海门运进，大多时候则没有。士兵们日渐消瘦，却仍不肯开门。1468年8月他们终于开城列队而出时，他们顽强坚守的故事化为了歌曲《哈勒赫的勇士》（Rhyfelgyrch Gwŷr Harlech）。",
  "britons:triumph": "想象：战队骑马沿山谷返回领主的宫廷（llys），马匹满身泥浆，少了两个人。女人们沿着小路跑出来，在骑手中寻找自家人的面孔。那一夜，蜜酒角杯在大厅里传递，首席诗人（pencerdd）站在火边，按名字逐一歌唱每个人的功绩。生者受到赞颂，死者受到更高声的赞颂。",
  "britons:build": "1805年11月26日，横跨迪河谷（Dyffryn Dyfrdwy）的庞特基西斯特渡槽举行通航典礼，船队列队驶过，乐队奏乐，山坡上鸣炮，约八千人围观。托马斯·特尔福德和威廉·杰索普把它的铁水槽架在近四十米高的石墩上。当地的石匠和工人在这里干了十年，只有一人丧生。",
  "britons:voyage": "1865年5月28日，运茶快帆船“含羞草号”载着约一百五十名威尔士男女老少从利物浦启航，他们是采石工、煤矿工和鞋匠，寻找一个能让自己的语言延续下去的地方。途中两个孩子夭折，两个孩子出生。7月28日，他们望见了巴塔哥尼亚（Y Wladfa）光秃秃的海岸，在马德林港登陆，在还不知道这片干燥土地将对他们提出怎样要求的时候，就在海滩上唱起了赞美诗。",
  "britons:festival": "1176年圣诞节，里斯·阿普·格鲁菲兹，即里斯勋爵（yr Arglwydd Rhys），在卡迪根（Aberteifi）的新城堡中举行盛大聚会，据编年史记载，此事提前一年就在威尔士内外广为宣告。诗人与诗人比赛，竖琴手、克鲁斯琴（crwth）手和风笛手彼此较量，两把椅子作为奖品，一把给了一位圭内斯的诗人，一把给了里斯勋爵自家一位年轻的竖琴手。它被铭记为第一届诗歌音乐节（eisteddfod）。",
  "britons:games": "亨利斯的乔治·欧文在1603年描述过“克纳潘”（cnapan）：每逢圣日，彭布罗克郡（Sir Benfro）的整个整个教区在空地上相聚，有时多达两千人，有些人骑着马。一只用牛油煮过、滑得握不住的木球被抛向空中，双方争抢着要把它带回自己的教区，越过田野、树篱和溪流，直到天黑。男人们带着伤痕和骄傲回来，这故事要讲上一整个冬天。",
  "britons:drought": "想象：一个干旱的夏天，里恩半岛的溪流细成了涓涓细水，山坡上的干草还没来得及割就变黄了。女人们拿着水罐和别针走到圣卡比（Cybi Sant）圣井，把别针投入水中，祈求圣人降雨。礼拜堂里，牧师也明明白白地为雨祷告。农民们望着西边，看海上有没有云。",
  "britons:quake": "1984年7月19日早晨，里恩半岛的大地震动起来。卡那封和普尔赫利的碗碟从橱柜上震落，烟囱开裂，利物浦和都柏林的人们也感觉到了。这是英国一个世纪以来最强烈的地震之一，却无人死亡。农舍里，人们一连几周都在谈论自己当时站在哪里，老人们说，是大山在睡梦中翻了个身。",
  "britons:winter": "1947年冬，威尔士（Cymru）从一月下旬开始下雪，一直下到三月。积雪埋没了树篱和小路，山地农场上成千上万只羊被闷死在雪里；男人们用长杆在雪堆中探寻呼吸留下的空洞，挖出羊来。村庄与外界隔绝了几个星期。冰雪消融时，牧羊人走遍山坡清点剩下的羊，许多农场不得不从头开始。",
  "britons:plague": "1349年黑死病（y Pla Du）传到威尔士时，诗人伊安·盖辛失去了自己的孩子，写下一首挽歌。他把瘟疫称作如黑烟般袭来的“先令头”死神，描述了那些脓包、小小的种子、腋下疼痛的“苹果”。他哭诉自己不得不亲手埋葬年幼的孩子。这是少数用威尔士语告诉我们那一年是何等滋味的声音之一。",
  "britons:wedding": "在旧时的威尔士，婚礼由邀客人（gwahoddwr）开始：他拄着挂满彩带的手杖，一家一家地走访农庄，念着押韵的邀请辞，请每户人家带一份礼物来。婚礼当天早上，新郎的朋友们来接新娘，却发现门被闩上了；双方隔着门对诗，这种较量叫作“蓬科”（pwnco）。有时新娘随后还会骑马逃走，得有人去追。",

  "english:siege": "1648年6月至8月，内战期间的科尔切斯特城遭到围困。一周周过去，城里人先吃马，再吃狗和猫，然后吃蜡烛和肥皂。妇女和儿童出城乞求围城者放她们通过，却被赶回城门。8月28日，城市投降。它的呢绒业就此衰败，城墙上至今仍可见炮弹的伤痕。",
  "english:triumph": "1415年11月23日，亨利五世在阿金库尔之战后骑马回到伦敦。城市沿着他的路线搭建了庆典布景：伦敦桥上的巨人，有少女歌唱的城堡，扮成天使撒下金箔的男孩，水渠里流淌着葡萄酒。国王本人只穿着朴素的紫袍，也不许人在他前面捧着他那顶伤痕累累的头盔，说荣耀归于上帝。唱诗班在街头唱着《感谢上帝，英格兰》（Deo gratias Anglia）。",
  "english:build": "1220年4月28日，主教理查德·普尔在老塞勒姆下方的水草地上为一座新大教堂奠下最初的几块基石：一块为教宗，一块为大主教，一块为他自己。石匠、木匠和车夫们干了三十八年，于是索尔兹伯里大教堂以单一的风格建成，轻盈、灰色而宁静。高大的尖塔是后来加的，至今仍是英格兰最高的尖塔，仍屹立在那片沼泽地上。",
  "english:voyage": "1620年9月，“五月花号”载着约一百名乘客离开普利茅斯，其中许多是寻求以自己的方式礼拜的家庭。随后是六十六天的秋季大风；一根主梁开裂，又被顶回原位；一个被卷下船的年轻人抓住了一根升降索，被拉了回来。11月9日，他们看见了科德角的沙丘。威廉·布拉德福德写道，他们跪倒在地，称颂上帝。",
  "english:festival": "五朔节的清晨，英格兰村庄的年轻人天亮前就到树林里去“迎五月”，带着绿枝和山楂花回来。最高的一棵树被砍下做五月柱。菲利普·斯塔布斯在1583年抱怨说，它要由二十到四十对牛拉回家，每头牛的角上都缀着花，然后竖起来，人们伴着笛子和鼓围着它跳上一整天。清教徒不以为然；村民们照跳不误。",
  "english:games": "在中世纪的英格兰，足球是全城参与的游戏。忏悔星期二那天，城这一头的男人们设法把一只皮球带到城的另一头，穿过街道、河流和墓地，人数不限。从1314年的爱德华二世起，国王们一再禁止它，嫌它吵闹又断胳膊断腿。在德比郡的阿什本，这项比赛至今每逢忏悔节仍要进行，一赛就是两天。",
  "english:drought": "1976年漫长的夏天，英格兰从五月到八月几乎滴雨未下。草坪变成褐色，水库萎缩成龟裂的泥地，在约克郡和威尔士部分地区，一家家人提着水桶在街头的竖管前排队取水。人们被劝告共用洗澡水，在马桶水箱里放一块砖。八月底政府任命了一位抗旱大臣；几天之内雨就来了，而且下了整整一个秋天。",
  "english:quake": "1580年4月6日傍晚，复活节周的星期三，一场地震震动了伦敦和肯特。威斯敏斯特的大钟自己响了起来，烟囱倒塌，在纽盖特的基督教堂，石块从屋顶砸向会众，砸死了两名年轻学徒托马斯·格雷和梅布尔·埃弗里特。几天之内就出现了小册子和民谣，称这是上帝要人悔改的警告。那年春天，许多人只是更勤地去教堂。",
  "english:winter": "1683年至1684年冬，泰晤士河冰封了两个月。约翰·伊夫林写道，冰面上搭起了一条货摊街，马车从威斯敏斯特驶往圣殿区，如履平地，还有斗牛、赛马、木偶戏和烤肉的厨子。印刷商在河上架起印刷机，出售印着你名字和“于泰晤士河上”字样的卡片。然而他也写到了冻死的鸟和没有柴火的穷人。",
  "english:plague": "1665年9月，瘟疫藏在一捆来自伦敦的布料中，传到了德比郡的埃亚姆村。教区长威廉·蒙佩森和前任牧师托马斯·斯坦利说服村民们自我封闭，不让疾病扩散。食物被放在村界石旁，村民把钱币放在醋里作为付款。约两百六十人死去，其中包括蒙佩森的妻子凯瑟琳；邻近的村庄得以幸免。",
  "english:wedding": "在中世纪的英格兰，婚誓在教堂门口说出，然后新人才进去望弥撒；乔叟笔下的巴斯妇人就夸口自己在教堂门口嫁过五个丈夫。结婚预告在此前三个星期天宣读过。之后是“新娘麦酒”，由新娘家酿造并卖给宾客，帮小两口起家。有些地方还会在新娘头上掰碎一块蛋糕讨个吉利，众人争抢碎屑。",
  "house-of-lancaster:siege": "1418年7月至1419年1月，亨利五世的军队围攻鲁昂。粮食耗尽时，城里把约一万两千名穷人赶出城门，而围城者不让他们通过。他们就在城墙与营地之间的壕沟里过活，吃草度日，婴儿在那里出生，被人用筐子吊上城去受洗。圣诞节那天，国王给他们送去了面包。英格兰士兵约翰·佩奇用诗句把这一切都记了下来。",
  "house-of-lancaster:triumph": "想象：夏末，弓箭手们从法国的战争中回到兰开夏郡，晒黑了，也瘦了，每人带着一包军饷和一肚子故事。教区教堂的钟声迎接他们归来。妻子和母亲们在桥头等候，卖酒的妇人开了一桶新酒。那晚在客栈里，风笛手吹起曲子，男人们给孩子们演示长弓能把箭射多远。",
  "house-of-lancaster:build": "1446年，亨利六世为剑桥新建的国王学院礼拜堂奠下第一块基石，打算把它建成全国最精美的礼拜堂。工程因战争中断，又在后来的国王治下重启。最终在1508年至1515年，石匠总管约翰·沃斯特尔建起了宏伟的扇形拱顶，一面如蕾丝般的石头天花板。一代代石匠为这座建筑劳作，却没有一个人既看到它开工又看到它完工。",
  "house-of-lancaster:voyage": "1497年5月，住在布里斯托尔的威尼斯人约翰·卡伯特获亨利七世特许寻找新土地，驾着小船“马修号”带着约十八人向西航行。约五周后，6月24日，他们望见了陆地，很可能是纽芬兰。他们短暂登岸，看到了有人的迹象，便返航回家。布里斯托尔的渔民由此得知有一片海满是鳕鱼，据说用筐子就能把鱼舀上来。",
  "house-of-lancaster:festival": "1520年6月，在加来附近，亨利八世与法国国王弗朗索瓦一世相会，连续欢宴十八天，那片田野后来被称为“金缕地”。人们用木材和彩绘布搭起一座临时宫殿，一座喷泉为所有来客流淌着红葡萄酒，两位国王的唱诗班一同唱弥撒。有骑枪比武、摔跤和宴会。方圆数里的平民都赶来围观、喝酒、跳舞。",
  "house-of-lancaster:games": "1511年2月，亨利八世在威斯敏斯特举行盛大的比武大会，庆祝儿子亨利王子的诞生。国王本人以“忠心爵士”之名上场比武。彩绘的《威斯敏斯特比武卷》描绘了骑手的行列和王家号手，其中有一位头戴黄色头巾的黑人号手约翰·布兰克。几天之内，小王子夭折了，宫廷从比武场转入哀悼。",
  "house-of-lancaster:drought": "1540年，一场大旱袭击了英格兰和欧洲大部分地区。从春到秋几乎滴雨未下；泰晤士河水位降得极低，海水倒灌过伦敦桥，河水变咸。水井干涸，牲畜死亡，热病随着坏水蔓延。然而葡萄熟得又早又甜，那年秋天的酒被人们记作喝过的最烈的酒之一。",
  "house-of-lancaster:quake": "1382年5月21日，一个教士会议正在伦敦黑衣修士院开会，大地震动起来。多佛尔海峡地震震裂了肯特的教堂塔楼，震落了坎特伯雷的尖顶。会议是为审判约翰·威克里夫的学说而召开的；双方都把这场震动看作上帝的征兆，却无法就其含义达成一致。它后来被称为“地震会议”。",
  "house-of-lancaster:winter": "1407年至1408年的冬天被世世代代记作“大霜冻”。编年史家写道，它从十二月持续到三月，泰晤士河封冻，画眉和乌鸫从树篱上冻死坠落。牛棚里的牛因缺干草而饿死。在兰开斯特王朝国王亨利四世治下，人们挤在泥炭火边，互相说着在世的人谁也没见过这样的严寒。",
  "house-of-lancaster:plague": "1485年8月，伦敦出现了一种新的疾病：汗热病。它以一阵寒战和狂跳的心脏开始，接着是大汗淋漓，几个小时就能致命。人们说，一个人午饭时还谈笑风生，晚饭时就死了。它一波接一波地卷土重来，1528年还侵入了王宫；亨利八世为了躲避它，坐立不安地从一处宅邸搬到另一处。",
  "house-of-lancaster:wedding": "1486年1月18日，亨利七世在威斯敏斯特迎娶约克的伊丽莎白，把厮杀了三十年的两个家族结合在一起。他们的徽章成了都铎玫瑰——一朵红玫瑰中间嵌着一朵白玫瑰，从礼拜堂天花板到儿童玩具，处处都雕着、画着。伦敦街头燃起篝火，分发葡萄酒。对许多人来说，这朵玫瑰的意思很简单：漫长的战乱或许结束了。",

  "celts:siege": "公元前52年，维钦托利（钱币上作Vercingetorixs）和约八万高卢人被困在山城阿莱西亚，四周是凯撒修筑的双重城墙和壕沟。粮食日渐短缺，城主曼杜比人把妇女、儿童和老人送出城，希望能放他们通过。罗马人拒绝了。他们在两道城墙之间等待，在两军的注视下挨饿，而守军则望着地平线，盼望大批援军的到来。",
  "celts:triumph": "约公元前100年游历高卢的波塞冬尼奥斯写道，战士们得胜归来时唱着凯歌，战利品和敌人的首级挂在马脖子上。接着便是宴会。最勇敢的人得到“勇士之份”——猪腿，有时还得为此决斗。吟游诗人拿着里拉琴起身，歌颂当天的功绩，每唱完一节，大厅里都爆发出吼声。",
  "celts:build": "凯撒详细描述了高卢城镇的城墙，因为它们难倒了他的工程师：长长的木梁成排横铺在墙中，用钉子连在一起，缝隙填满泥土，外面砌着巨石。石头防火，木头防攻城槌。在比布拉克特和其他设防城镇（oppida），整个整个的村社修筑起这样的城墙，考古学家至今仍在废墟中发现前臂那么长的铁钉。",
  "celts:voyage": "公元前278年，约两万高卢人——其中只有一半是战士，其余是带着大车的妇女、儿童和老人——应比提尼亚国王之邀作为盟友，渡过海峡从欧洲进入亚洲。他们漂泊多年，最终定居在安纳托利亚中部的高原上。他们在那里把自己的语言保留了好几个世纪；约公元390年，圣哲罗姆写道，加拉太人说的话和莱茵兰的特雷维里人差不多。",
  "celts:festival": "十一月一日的萨温节（古爱尔兰语Samain）是爱尔兰一年的开始。一连三天，国王和百姓聚集在塔拉（Teamhair）和其他王家之地，宴饮、集会、议定法律。故事里说，萨温之夜，异界山丘（sídhe）的门敞开着，死者和仙人在外游荡。人们在特拉赫特加山上点起篝火，家家的炉火都从这里重新引燃。",
  "celts:games": "爱尔兰传说讲到泰尔滕集会（Óenach Tailten），每年卢纳萨节举行，以纪念卢格神的养母泰尔丘——她为开垦平原耕作而劳累至死。集会上有赛马、赛跑、掷矛和板棍球（iománaíocht），有诗人和讲故事的人，还有贸易集市。在故事里，少年库丘林用球棍赶着一只球来到艾汶玛卡，独自一人击败了一百五十个少年。",
  "celts:drought": "想象：夏日的骄阳把高卢平原上的草晒成了褐色，圣林中的泉水只剩一线细流。人们带着供品走去：小小的青铜车轮、雕成病人模样的木像、一头小牛。德鲁伊把牛奶倒进泉中，呼唤着水之女神的名字对她说话。农民们默默站着，眼睛望着西边的天空。",
  "celts:quake": "想象：一天夜里，高卢人的一座山城下大地震动。陶罐摔落，牛在栏里哞叫，一段城墙滑进了壕沟。早晨，人们聚集在神龛旁，惊恐地七嘴八舌，德鲁伊说是大地母亲在睡梦中翻了身。他们在坑里埋下一份青铜供品，男人们赶在收获之前开始重修城墙。",
  "celts:winter": "想象：西部一座圆屋里的隆冬。牛关在屋旁的牛棚里，它们的热气透过枝条编的墙传过来。雪覆盖着茅草屋顶，炊烟从中袅袅飘出，储存的谷物和熏肉又被清点了一遍。在漫长的黑暗中，讲故事的人讲起库丘林少年时的故事，人人都在等待圣布里吉德节（Imbolg）和母羊的第一口奶。",
  "celts:plague": "爱尔兰编年史记载，664年8月1日，一场名为“黄疫”（buide Conaill）的大瘟疫传到了爱尔兰（Éire）。它夺走了国王、修道院长和平民的生命，无分贵贱；比德写道，它使不列颠和爱尔兰的整片整片地区人烟断绝。修士们逃到小岛上，许多人祈求幸免。有人说，疾病之所以降临，是因为人太多，土地养不活了。",
  "celts:wedding": "凯撒记下了高卢人的一个习俗：男人娶妻时，要从自己的财产中拿出与新娘嫁妆等额的一份。两份财产合在一起保管，收益积存下来，夫妻中谁活得更久，谁就得到两份连同多年的全部收益。在爱尔兰，卢纳萨（Lughnasadh）集市上的婚姻可以是为期一年零一天的试婚，到期只需各自走开便告结束。",

  "franks:siege": "885年11月，数百艘维京船沿塞纳河而上，围攻巴黎（Parisius）——那时它是一座有两座设防桥梁的岛城。主教戈兹林和伯爵厄德率市民坚守城墙。北桥的塔楼被洪水切断后，十二名守军一直战斗到全部阵亡。围城持续了将近一年。圣日耳曼修道院的修士阿博用拉丁文诗句记下了这一切（《巴黎城之战》，Bella Parisiacae urbis）。",
  "franks:triumph": "796年，法兰克人攻入阿瓦尔人在匈牙利平原上的巨大设防营地“环”，找到了阿瓦尔人两个世纪以来积聚的财宝。艾因哈德写道，财宝用十五辆大车运往亚琛（Aquisgranum），每辆由四头牛拉着。查理曼把其中大部分赠给了教会、教宗和他的追随者。法兰克人说，他们从未如此富有。",
  "franks:build": "约796年，查理曼开始修建亚琛礼拜堂，一座带回廊和穹顶的八角形石砌教堂，在阿尔卑斯山以北前所未见。它的建筑师是梅斯的奥多（Odo Mettensis）。大理石和斑岩柱子从罗马和拉文纳用车船翻越阿尔卑斯山运来。礼拜堂于805年祝圣，查理曼那张朴素的石头宝座至今仍立在回廊上。",
  "franks:voyage": "797年，查理曼向巴格达的哈里发哈伦·拉希德派出使团。三名使者中只有一位名叫以撒的犹太人回来了，他带回一份礼物：一头名叫阿布·阿拔斯的大象。它从非洲渡海到意大利，熬过冬天，然后翻越阿尔卑斯山。802年7月20日，它抵达亚琛，法兰克人从四面八方赶来看它。",
  "franks:festival": "图尔的格雷戈里讲述，法兰克国王克洛维在圣诞节于兰斯受洗，大约是在496年或稍晚几年。街道上挂满彩绘的布幔，教堂装饰着白色帷幕，洗礼堂里满是蜡烛和馨香，法兰克人以为自己置身于天堂的芬芳之中。格雷戈里说，和他一起受洗的还有他的三千名战士。",
  "franks:games": "842年，两位法兰克国王在沃尔姆斯（Wormatia）为他们的军队举行竞技。亲临现场的尼特哈德写道，人数相等的萨克森人、加斯科涅人、奥斯特拉西亚人和布列塔尼人队伍全速向对方冲去，如同作战，然后掉头用盾牌护住后背撤开，再轮流转身追逐对方。最后国王们也和所有年轻人一起加入。他说，没有一个人受伤。",
  "franks:drought": "792年和793年，一场可怕的饥荒袭击了法兰克各地，编年史记载，有些地方的人被迫在大斋期吃肉。次年，在法兰克福（Franconofurd）宗教会议上，查理曼规定了谷物和面包的价格，不让穷人被卖家逼得挨饿，并命令他自己的庄园按此价格出售。他还嘱咐各教会祈祷并施舍。",
  "franks:quake": "《法兰克王国编年史》记载，801年4月30日夜间二时，一场大地震袭来，整个意大利都有震感；罗马圣保罗大殿的屋顶塌了下来。查理曼当时正从罗马启程回国。编年史说，同年莱茵河沿岸各地也发生了地震，随后疫病流行。法兰克修士们仔细地记下这些事，视为需要参悟的征兆。",
  "franks:winter": "法兰克编年史把763年至764年的冬天记作有史以来最严酷的冬天之一。冰雪从十月初一直持续到春天。河流冻得大车可以从冰上驶过，南方的橄榄树和葡萄藤冻死了，旅人们说，东方连黑海的部分海面都结了冰。在村庄里，农民们清点死去的牛，等待解冻。",
  "franks:plague": "图尔的格雷戈里描述了571年传到克莱蒙（Arverna）的瘟疫，那种使腹股沟肿胀的疾病。他写道，一个星期天，圣彼得大殿里躺着三百具尸体。棺材用完了，十具甚至更多的尸体被埋在同一个坑里。主教加卢斯带领民众吟唱、禁食、列队游行，走向各圣人的教堂，祈求城市得以幸免。",
  "franks:wedding": "在法兰克人中，男子要向女方家庭支付聘礼以求娶她，新婚之夜后的早晨，他还要送给妻子一份“晨礼”（Morgengabe），归她个人所有。图尔的格雷戈里提到过王后们的晨礼：高卢南部的整座整座城镇被赠给王家新娘。对普通人家来说，这份礼物可能是一头牛、一件斗篷或一份土地。",

  "french:siege": "1870年9月至1871年1月，巴黎被包围，与外界隔绝。信件乘着气球从蒙马特尔飞出，鸽子则带着微缩胶片上的回信飞回。粮食耗尽后，巴黎人吃马，然后吃猫、狗和老鼠；圣诞节时，瓦赞餐厅供应大象清汤，取自植物园的卡斯托尔和波吕克斯。妇女们在严寒中通宵排队等面包，人们就这样撑过了冬天。",
  "french:triumph": "1214年夏，腓力·奥古斯都（Philippe Auguste）从布汶大捷中凯旋。编年史家纪尧姆·勒布勒东写道，一路上，农民和收割者丢下麦捆前来观望，村村敲响钟声，教堂挂起挂毯和绿枝。在巴黎，各学校的学生连续七天七夜唱歌跳舞，全城欢喜得无法入眠。",
  "french:build": "1144年，海蒙院长（abbé Haimon）记述了沙特尔的一桩奇事：各阶层的男男女女亲自套上大车，拉着石头、木材和粮食去建造大教堂，上千人默默拉车，或唱着赞美诗、忏悔罪过，只在祈祷时才停下。1194年大教堂被烧毁后，他们又重新建造，几十年间建起了那座至今仍屹立的宏伟教堂。",
  "french:voyage": "1534年4月20日，雅克·卡蒂埃带着两艘船和六十一人离开圣马洛，去寻找向西的通道。不到二十天，他们望见了纽芬兰，随后沿拉布拉多海岸航行，卡蒂埃称那里是“上帝赐给该隐的土地”。在圣劳伦斯湾，他们遇到了乘独木舟的米克马克人，对方用棍子挑着毛皮要做交易。九月，他们回到了圣马洛。",
  "french:festival": "在中世纪法国的大教堂里，圣诞节后的日子会迎来愚人节（Fête des Fous），年轻的神职人员把世界颠倒过来。1月14日在博韦，一个怀抱婴儿的女孩骑着驴被领进教堂，过“驴节”（Fête de l'Âne），纪念逃往埃及。弥撒每一部分结束时，会众不说“阿们”，而是学驴叫三声作答。",
  "french:games": "掌球游戏（jeu de paume）在中世纪法国起初是赤手打，后来戴手套、用球拍，在庭院和室内球场里进行。1316年，国王路易十世在万塞讷打了一场激烈的球，随后在阴凉的地窖里喝了大量冰凉的葡萄酒，病倒去世。这项游戏依然是国王和市民的心头所好，到1600年，巴黎已有数百座球场。",
  "french:drought": "想象：普罗旺斯一个干旱的夏天，罗讷河水位低落，塔拉斯孔周围的田地龟裂。全城抬着主保圣女玛尔大（sainte Marthe）列队走到河边，敲鼓吹笛，祈求降雨。农民们赤脚跟在后面。老妇人们讲起玛尔大如何驯服河中怪兽塔拉斯克的故事，说她肯定能带来一点水。",
  "french:quake": "1909年6月11日傍晚，一场地震袭击了普罗旺斯朗贝斯克、罗涅和圣卡纳一带的村庄。老石屋倒塌，压在正吃晚饭的一家家人身上，约四十六人死亡。士兵们从马赛赶来在瓦砾中挖掘。这是法国一个世纪以来最强烈的地震。幸存者在田野里的帐篷中住了好几个星期，提心吊胆地听着余震。",
  "french:winter": "1709年1月，一场极其酷烈的严寒袭击法国，被称为“大寒冬”（Grand Hiver）。圣西门公爵写道，凡尔赛宫桶里和瓶里的酒都结了冰，塞纳河冻得结结实实。胡桃树和橄榄树冻死，冬小麦冻死在地里。到了第二年春天，乡下的穷人饥寒交迫，许多人死于饥荒和寒冷。",
  "french:plague": "1720年5月，“大圣安托万号”把瘟疫带到了马赛。几个月内，半个城市的人死去。贝尔松斯主教走遍街巷为垂死者行终傅礼，罗兹骑士带领服苦役的犯人，把堆积在拉图雷特广场上的尸体清运到填满生石灰的旧堡垒里。一道大墙——“瘟疫墙”（mur de la peste）——横贯普罗旺斯修筑起来，以阻止疾病蔓延。",
  "french:wedding": "在法国乡村，婚礼队伍跟在村里的提琴手（ménétrier）后面走向教堂，他一路拉琴去，一路拉琴回，然后为通宵的舞会伴奏。新娘的袜带有时会被剪成小段，分给年轻小伙子们。寡妇或鳏夫再婚时，年轻人可能会闹“喧闹婚”（charivari），在他们窗下敲锅打盆，直到用酒打发走为止。",

  "jeanne-darc:siege": "从1428年10月起，奥尔良人就生活在城墙之后，四周被英军的堡垒包围。市民与士兵并肩站岗，妇女们把石块和沸水运上城墙，钟楼的大钟为每一次进攻报警。面包先是变贵，后来变得稀缺。1429年4月29日，消息传开：圣女（la Pucelle）带着运粮队来了；那天夜里，全城的人举着火把涌上街头去看她。",
  "jeanne-darc:triumph": "1429年5月8日，英军解除奥尔良之围撤走了。民众和士兵列队绕城墙而行，走向各个教堂，唱着感恩的赞美诗，贞德也在其中。市议会决定每年重演这一游行。此后几乎每年5月8日都举行游行，钟声齐鸣，旗帜飘扬，还有一位奥尔良姑娘骑马扮演圣女。",
  "jeanne-darc:build": "1481年，洛林的圣尼古拉-德波尔开始兴建一座大教堂，用以供奉圣尼古拉（saint Nicolas）的一节指骨圣髑。几百年来它吸引着朝圣者，据说贞德本人在前往法兰西之前也曾来过。石匠们用约六十年建起了它的两座高塔和纤细的柱子，那是洛林最高的柱子。每年十二月，洛林人仍会前来敬拜这位孩子们的圣人。",
  "jeanne-darc:voyage": "1429年2月，贞德女扮男装，带着六名同伴离开沃库勒尔，骑马前往希农去见王太子。这段路程穿过敌占区，走了十一天。他们大多在夜间赶路，渡过被冬雨涨满的河流，睡在地上。同伴们后来说，她从不抱怨，每天都想听弥撒。终于，希农的塔楼出现在维埃纳河上方。",
  "jeanne-darc:festival": "栋雷米附近有一棵大山毛榉，叫作“夫人树”（l'Arbre des Dames），旁边有一眼据说能治热病的泉水。贞德告诉法官，大斋期的一个星期日，叫作“泉水星期日”（dimanche des Fontaines），村里的年轻人会到树下去，给树挂上花环，吃专为那天烤的小面包，喝泉水，唱歌跳舞。她说她自己也在那里编过花环。",
  "jeanne-darc:games": "想象：洛林一个村庄的夏日节庆，年轻小伙子们在教堂前的草地上摆起木柱（quilles）。每人轮流掷出沉重的木球，老人们为每一根倒下的木柱大声争论。姑娘们在树荫下观看，提琴手拉着琴，赢家得到一块蛋糕，还有权挑选晚上第一支舞的舞伴。",
  "jeanne-darc:drought": "想象：默兹河谷一个干旱的夏天，河水在白石间萎缩，燕麦又矮又稀。栋雷米的神父在祈祷日带领全村出行，举着十字架和旗帜绕行田界，吟唱诸圣连祷文，祝福庄稼。孩子们用棍子敲打界石，好让自己记住。每唱完一节，人人都抬头望天。",
  "jeanne-darc:quake": "1682年5月12日，一场地震袭击了洛林的南孚日山区，雷米尔蒙和普隆比耶尔一带。烟囱倒塌，教堂拱顶开裂，雷米尔蒙修女会的大修道院也受了损。人们在夜里跑出家门，待在田野里，向圣罗马里克祈祷。这至今仍是那片山区有记录以来最强的地震，村庄世世代代都记得它。",
  "jeanne-darc:winter": "想象：栋雷米漫长的冬天。雪积在屋顶上，一家人紧紧围坐在炉火旁。贞德的母亲伊莎贝尔一边纺线，一边教女儿念天主经、圣母经和信经——这就是贞德一生所受的全部教育。父亲在修补马具。当教堂的晚祷钟声越过雪野传来，女孩像往常一样跪了下来。",
  "jeanne-darc:plague": "想象：战乱年间一个炎热的夏天，瘟疫来到了洛林的一个村庄。房屋被封闭并做上记号，死者在夜里被抬出去。村民们向圣洛克——那位身旁跟着一条狗、腿上带着疮的朝圣圣人——许愿：若他保全其余的人，就为他建一座礼拜堂。秋天到来，疫病过去，他们亲手把它建了起来。",
  "jeanne-darc:wedding": "1428年，图勒的一个年轻人声称贞德曾答应嫁给他，把她告上了教会法庭。她的父母本希望她接受。约十六岁的贞德独自前往图勒，发誓她从未作过这样的承诺；她早已向上帝许下了守贞之愿。法官判她胜诉。这是唯一一次为她筹划的婚事，而她拒绝了。",

  "knights-templar:siege": "1189年至1191年，十字军围攻阿卡，而萨拉丁的军队又反过来包围了他们的营地。1190年冬，饥饿袭击了围城者：一袋粮食要价连城，骑士们杀了自己的战马来吃，连内脏也不放过。圣殿骑士把所有的东西分给大家。人们嚼草啃骨头。终于有船运来了粮食，营中唱起了《赞美颂》（Te Deum）。1191年7月，城市投降。",
  "knights-templar:triumph": "1177年11月25日，身患麻风病的少年国王鲍德温四世率领一支小军队，连同约八十名圣殿骑士，在蒙吉萨尔奇袭了萨拉丁兵力多得多的军队。圣殿骑士的冲锋击溃了敌军，萨拉丁骑着一匹快骆驼逃走。在耶路撒冷，钟声齐鸣，神职人员和百姓在圣墓教堂唱起《赞美颂》，圣殿骑士则在自己的礼拜堂中谢恩。",
  "knights-templar:build": "1185年2月，耶路撒冷宗主教赫拉克利乌斯来到伦敦，为圣殿骑士在泰晤士河畔新建的圆形教堂祝圣，它是仿照圣墓教堂的形制建造的。石匠们用珀贝克大理石做成纤细的柱子，这种风格在英格兰前所未有。圣殿教堂至今仍在，地上躺着骑士的卧像，唱诗班仍唱着素歌。",
  "knights-templar:voyage": "想象：马赛的春天。一艘圣殿骑士的船载上朝圣者、马匹、布匹和白银，驶向东方。他们航行数周，经过西西里和克里特，每天傍晚，随军神父在甲板上唱晚课，朝圣者们跪在麻袋之间。一天早晨，一名水手喊了起来：阿卡低平的海岸已在望。朝圣者们流着泪唱起《赞美颂》。",
  "knights-templar:festival": "在耶路撒冷，最盛大的节日是复活节。圣星期六，成群的朝圣者——拉丁人、希腊人、亚美尼亚人和叙利亚人——在圣墓教堂（Sanctum Sepulchrum）里等待圣火，据说那是在圣墓中自行燃起的火焰。沙特尔的富尔彻描述了1101年圣火迟迟未至时人们的焦灼。圣火来了，便从一支蜡烛传到另一支，教堂里充满了光明和歌声。",
  "knights-templar:games": "圣殿骑士团会规禁止弟兄们下国际象棋或玩“棋盘戏”（tables，即后来称为双陆的骰子游戏），因为它们导致懒惰和赌博。它只作了一点小小的通融：弟兄们可以在刻于石头上的棋盘上玩直棋（marelles，三子棋或九子棋），前提是不下赌注、只为娱乐。这样的棋盘至今仍可在他们城堡的石凳和墙上找到。",
  "knights-templar:drought": "1185年，耶路撒冷全境雨水断绝，饥荒迫在眉睫。王国的领袖们向萨拉丁请求停战，他同意了。编年史家记载，甚至有粮食被运进来供养基督徒的城镇。在那一季里，蓄水池空着，田地干涸，圣殿骑士和他们的邻人仰望天空，盼着同一场雨。",
  "knights-templar:quake": "1202年5月20日黎明前，一场大地震震撼了地中海东岸。在阿卡，王宫和许多房屋倒塌，提尔的城墙崩塌。圣殿骑士的城堡受损，弟兄们不得不重建塔楼和城墙。朝圣者写信回家说，大地像海一样起伏。圣殿骑士们在废墟中唱着日课，然后动手干活。",
  "knights-templar:winter": "1191年至1192年冬，十字军冒着冰冷的雨、冰雹和雪向耶路撒冷进军。马匹死在泥泞里，食物腐烂，盔甲生锈。在距城仅一天路程的贝特努巴，圣殿骑士和医院骑士进言说，即便攻下城池也守不住。军队掉头返回。编年史家写道，人们一边下山，一边哭泣咒骂。",
  "knights-templar:plague": "1218年和1219年，十字军围攻埃及的达米埃塔，圣殿骑士也在其中。帕德博恩的奥利弗记载了营中的一种疾病：牙龈肿胀，牙齿松动，双腿发黑。冬天里许多人死去。1219年11月军队终于入城时，发现城里满是死人，因为疾病和饥荒也袭击了守军。",
  "knights-templar:wedding": "圣殿骑士宣誓守贞，但会规允许已婚男子作为附属弟兄（confratres）加入。他们不能穿白斗篷，那是独身骑士专有的；他们还必须承诺，死后将一半财产留给骑士团。已婚男子可以一边与妻子同住，一边为圣殿效力，许多家庭就是以这种方式支持骑士团的。",

  "burgundians:siege": "1474年7月至1475年6月，大胆查理围攻莱茵兰城市诺伊斯长达十一个月。市民们坚守城墙熬过冬天，吃掉了自己的马，还用空心炮弹把消息射过河去。一位编年史家写道，城里的妇女把石块运上城墙，唱着歌给自己壮胆。公爵最终解除了围城，此后诺伊斯每年都庆祝这次坚守。",
  "burgundians:triumph": "1458年4月，好人腓力隆重入城根特（Gent）。城市沿着他的路线搭起舞台，上演由演员摆出的“活人画”（tableaux vivants）。其中一幕再现了凡·艾克兄弟的《根特祭坛画》，由真人歌手和乐师扮演天使。市民们穿上最好的衣服站满街道，葡萄酒流淌，公爵在欢呼声中骑马穿过，全城的人都涌出来看这场表演。",
  "burgundians:build": "1383年，勇敢的腓力（Philippe le Hardi）在第戎城外创建了尚莫尔加尔都西会修道院，为他的家族祈祷。石匠、画师和雕刻家在这里干了许多年。在修道院回廊里，克劳斯·斯吕特雕刻了《摩西井》（Puits de Moïse），六位先知环绕着一座泉，栩栩如生，仿佛就要开口说话。朝圣者前来触摸这口井，修士们的圣咏日夜回荡在回廊中。",
  "burgundians:voyage": "后来的传说把勃艮第人的起源追溯到波罗的海的博恩霍尔姆岛。到413年，他们已进入罗马领土，定居在莱茵河畔的沃尔姆斯一带；436年遭到惨败之后——这场惨败被铭记在《尼伯龙根之歌》中——幸存者于443年在日内瓦湖周围的萨保迪亚获得了新的土地。家家户户带着大车和牛群再次南迁，直到湖泊和阿尔卑斯山出现在眼前。",
  "burgundians:festival": "15世纪的第戎有一个名叫“疯妈妈”（Mère Folle）的狂欢社团，成员数以百计，从鞋匠到贵族都有。狂欢节时，他们穿着绿、红、黄三色服装在街上游行，乘着彩车，敲鼓吹笛，用勃艮第方言唱着讽刺城中丑闻的歌。“疯妈妈”本人——一个穿着裙子的男人——主持着这场欢闹。",
  "burgundians:games": "1449年和1450年，骑士雅克·德·拉兰在索恩河畔沙隆附近举办了“泪泉关隘”比武（Pas de la Fontaine des Pleurs）。一座帐亭搭在泉边，泉上画着一位哭泣的女子，任何骑士都可以触碰三面盾牌之一向他挑战。一年之中，每月第一天，他与所有来者交手，每一次都赢了。",
  "burgundians:drought": "自1354年起，博讷的葡萄园一直记录着每年开始采收葡萄的日期。1540年，全欧洲遭遇可怕的大旱，那年的采收在八月中旬就开始了，几乎比其他任何一年都早。葡萄又小又干瘪，但酿出的酒极烈，人们记了几十年。酿酒人望着焦渴的山坡，为每一串葡萄谢恩。",
  "burgundians:quake": "图尔的格雷戈里和阿旺什的马略记载，563年，罗讷河注入日内瓦湖（lac Léman）处附近一座名叫陶雷杜努姆的山崩塌了。一道巨浪冲下湖面，淹没了沿岸村庄，漫过日内瓦城墙，许多人丧生。桥梁和磨坊都被冲走了。古老的勃艮第王国的人们记住了湖水涌起的那一年。",
  "burgundians:winter": "1477年1月5日，在风雪和严寒中，勃艮第公爵大胆查理战死于南锡城外。两天后，人们在一个结冰的池塘里找到了他的遗体，衣物被剥光，一半已被狼吃掉，只有他的侍从和御医凭着旧伤疤和长指甲才认出了他。勃艮第人为他哭泣，而他们那个音乐如此丰富的伟大公国，被别人瓜分了。",
  "burgundians:plague": "想象：一个炎热的夏天，瘟疫来到了第戎。富人逃往乡间宅邸；穷人留了下来。圣贝尼涅教堂的丧钟一遍又一遍地响起，各善会把死者抬往墓地。市民们赤着脚，跟在圣人的圣髑后面列队游行，唱着连祷文。秋天到来，疫情缓解，他们点起比人还高的谢恩蜡烛。",
  "burgundians:wedding": "1468年7月3日，大胆查理在达默迎娶约克的玛格丽特，布鲁日（Brugge）随后举行了九天的盛宴，令全欧洲惊叹。奥利维耶·德·拉马什描述了当时的情景：一个里面藏着乐师的大馅饼，一头肚里有塞壬歌唱的机械鲸鱼，一个牵着单峰驼的巨人，还有在集市广场上举行的“金树比武”（Pas de l'Arbre d'Or）。喷泉流淌着葡萄酒，布鲁日的市民在街上跳舞。",

  "dutch:siege": "1574年，莱顿被围困了好几个月，城中百姓饥饿不堪；数千人死于饥饿和瘟疫。为了接近他们，人们掘开堤坝，让城市周围的土地慢慢被淹没，好让平底船驶过田野。1574年10月3日，救援船队抵达城下，分发鲱鱼和白面包。莱顿至今仍用鲱鱼、白面包和胡萝卜洋葱炖菜（hutspot）庆祝10月3日（Leidens Ontzet，莱顿解围日）。",
  "dutch:triumph": "1628年9月，皮特·海恩在古巴外海的马坦萨斯湾不战而俘获了西班牙运银船队。1629年1月，他的船队满载白银、黄金、靛蓝和胭脂虫回到国内，举国欢庆，公司的股东们分到了巨额红利。孩子们至今仍唱着那首歌：“皮特·海恩，皮特·海恩，名字虽小，功绩却大”（Piet Hein, Piet Hein, zijn naam is klein, zijn daden bennen groot）。",
  "dutch:build": "1927年，阿夫鲁戴克大堤开工，这道长三十二公里的堤坝要把须德海与北海隔开。工人们在海底铺下柳枝编成的沉排，从驳船上倾倒冰碛黏土。1932年5月28日，最后一个缺口合龙，两端相接时工人们欢呼起来。那里的一座纪念碑上写着：一个有生命力的民族，为自己的未来而建设（Een volk dat leeft, bouwt aan zijn toekomst）。",
  "dutch:voyage": "1642年8月，阿贝尔·塔斯曼（Abel Janszoon Tasman）带着“海姆斯凯克号”和“泽汉号”两艘船离开巴达维亚，去寻找一块巨大的南方大陆。11月24日，他的船员望见一片高耸的森林海岸，他将其命名为安东尼·范迪门之地，即今天的塔斯马尼亚。一名船上的木匠游过浪涛上岸，把一面旗帜插在一根柱子上。12月，他们望见了一片陆地的山脉，命名为斯塔滕兰，后来称为新西兰。",
  "dutch:festival": "12月5日前夜，荷兰孩子们在壁炉边放一只鞋留给圣尼古拉（Sinterklaas），还为他的马放上胡萝卜或干草。扬·斯特恩在1660年代画下了那天早晨：一个小女孩抱着她的娃娃和一桶糖果，一个男孩在哭，因为他的鞋里只有一根桦木条，其他人在笑，祖母则招手让他过去，她在床帘后面藏了一份礼物。",
  "dutch:games": "在17世纪的寒冬，运河和湖泊结冰时，全荷兰的人都到冰上去。亨德里克·阿维坎普一遍又一遍地画下这样的场景：手拉手滑行的溜冰者，马拉的雪橇，摔倒的孩子，还有玩“科尔夫”（kolf）的男人，用弯头球棍把球击过冰面打向一根柱子。富人和穷人共享同一片冰，一个热饮摊（koek-en-zopie）卖着热饮。",
  "dutch:drought": "想象：圩田里一个漫长干燥的夏天。田间的沟渠缩成了绿色的泥浆，牛站在沟边哞叫。风车现在倒着转，把河水抽进田里，而不是抽出去。在泥炭地带，一场火在地下闷烧了几个星期，从地里冒着烟。农民们星期天去教堂，专心聆听祈雨的祷词。",
  "dutch:winter": "1596年，威廉·巴伦支和他的船员被冰困在北极的新地岛外。他们用浮木和船上的木料造了一座房子，叫作“避难屋”（Behouden Huys），在里面度过了极夜：烧煤、设套捕狐狸、击退北极熊。为了提振士气，他们还过了主显节前夜的宴会。1597年6月，他们乘两艘敞篷小船离开；巴伦支死在了途中。",
  "dutch:plague": "1663年和1664年，瘟疫袭击了当时欧洲最繁忙的港口阿姆斯特丹；约两万四千人死去，或许每八人中就有一人。城市在城墙外设立了瘟疫院（pesthuis），病人被装在有盖的担架上抬去。来自疫区港口的船只被扣在海上。家家闭门，老教堂的丧钟几乎响个不停，而贸易一如既往地继续着。",
  "dutch:wedding": "在17世纪的荷兰婚礼上，宾客们会收到“新娘糖”（bruidsuikers），即糖衣杏仁，喝的是“新娘之泪”（bruidstranen），一种漂着金箔的香料白兰地。新娘戴着鲜花或绿叶编的花冠，新人的朋友们用花环装饰大门。常常有一只彩绘木箱——新娘箱（bruidskist）——装着她的亚麻织品，在乐师的演奏声中被列队抬到她的新家。",

  "spanish:siege": "公元前134年至前133年，罗马将军小西庇阿用城墙和塔楼包围了位于今卡斯蒂利亚的山城努曼西亚（Numancia）。城内的凯尔特伊比利亚人拒绝投降。阿庇安写道，随着饥饿加剧，他们吃皮革，然后吃草，最后吃死人。到最后，许多人宁死也不被俘。塞万提斯后来把他们的故事写成悲剧《努曼西亚》，卡斯蒂利亚人从此一直敬仰他们的勇气。",
  "spanish:triumph": "想象：一个西班牙方阵（tercio）的士兵们在佛兰德和意大利征战多年后，回到卡斯蒂利亚（Castilla）的家乡村庄。他们出现在大路上时，教堂的钟声响起，他们瘦削黝黑，外衣打满补丁。母亲们跑出来在一张张脸中寻找。在广场上，村长打开一皮囊葡萄酒，一个男孩吹起杜尔赛纳管（dulzaina）、敲着鼓，老人们缠着要听故事，直到月上中天。",
  "spanish:build": "1563年4月23日，埃斯科里亚尔（San Lorenzo de El Escorial）奠下第一块基石，这是马德里以北山中一座集修道院、宫殿和教堂于一体的建筑。建筑师胡安·包蒂斯塔·德·托莱多和后来的胡安·德·埃雷拉用灰色花岗岩建造了它，严峻而朴素。数千名石匠、车夫和工人在这里劳作了二十一年。1584年9月13日，最后一块石头安放就位，修士们开始在这里咏唱每日的日课。",
  "spanish:voyage": "1492年8月3日，“圣玛利亚号”、“平塔号”和“尼尼亚号”三艘船载着约九十人从帕洛斯启航。几个星期过去了，不见陆地，水手们又怕又怒。10月12日凌晨，“平塔号”上的水手罗德里戈·德·特里亚纳在月光下看见一片白色的沙岸，高喊：“陆地！陆地！”（Tierra! Tierra!）黎明时分，他们登上了巴哈马群岛中的一座岛屿。",
  "spanish:festival": "托莱多的基督圣体节，街道上挂满挂毯，搭起遮阳篷，路面撒满迷迭香和百里香。巨人和大头人偶（gigantes y cabezudos）在街上跳舞；过去还有一条名叫塔拉斯卡的龙，背上骑着一个人偶，冲着人群张嘴乱咬。然后大教堂巨大的银质圣体光座经过，人们安静下来，跪倒在地。",
  "spanish:games": "17世纪马德里的主广场上，节庆时会举行“掷杖游戏”（juego de cañas），这是卡斯蒂利亚人从摩尔骑手那里学来的。身着华丽服装的贵族队伍骑马冲向对方，投掷轻巧的藤杖，用皮盾接住，然后全速掉头离开。阳台上挤满了观众，全城的人都来观看和下注。",
  "spanish:drought": "想象：拉曼查平原自冬天以来就没下过雨。麦子又矮又黄，井水下降了。村民们把圣母（la Virgen）像从山上的隐修小堂抬到教区教堂，举行祈雨游行，男人们在烈日下光着头，女人们念着玫瑰经。他们许诺，不下雨，圣母就一直留在村里。",
  "spanish:quake": "1755年11月1日万圣节早晨，里斯本大地震也震撼了西班牙南部。塞维利亚（Sevilla）和萨拉曼卡的教堂塔楼开裂。一小时后，一道巨浪袭击了加的斯和韦尔瓦的海岸；在阿亚蒙特和安达卢西亚沿海的其他城镇，许多人溺亡。人们说，在加的斯，一位神父在城门口举起圣母的旗帜，海水便停住了。",
  "spanish:winter": "想象：卡斯蒂利亚高原上的十二月。从山脉吹来的风刺透每一件外衣，每天早晨，霜把麦茬染白。在村庄里，这是杀猪（matanza）的时节：全家人聚在一起，灌香肠、做血肠，大家共享一顿漫长的大餐。火里添着葡萄藤根，老牧羊人讲着山里的故事。",
  "spanish:plague": "1649年春夏，瘟疫袭击了当时欧洲最富有的城市之一塞维利亚（Sevilla）。几个月内，近一半的居民，约六万人死去。运尸车在街上隆隆驶过，驶向城外的大坑。画家穆里略经历了这一切；他后来画的许多穷孩子，就是那一年的孤儿。这座城市的荣光再也没有完全恢复。",
  "spanish:wedding": "在卡斯蒂利亚的婚礼上，新郎送给新娘十三枚硬币（arras），常常装在一个小银盒里，由神父祝福。它们象征着他照顾她、照顾两人共同家庭的承诺。新人跪下时，可能会有一根绳索或花带（lazo）绕在他们肩上。然后宾客们在教堂门口撒米，宴席和舞蹈一直持续到深夜。",

  "portuguese:siege": "1384年5月至9月，一支卡斯蒂利亚军队从陆上和河上围攻里斯本（Lisboa）。编年史家费尔南·洛佩斯描述了城中的饥饿：母亲们没有东西给孩子吃，小男孩们在街上哭着要面包，人们吃草和兽皮。后来，围城军营中爆发了瘟疫，并迅速蔓延。九月，围城解除，里斯本感谢上帝让它坚持了下来。",
  "portuguese:triumph": "1499年夏，瓦斯科·达·伽马的船队从印度回到里斯本，这是第一支绕过非洲经海路抵达印度的船队。三分之二的人死在了航行途中，其中包括瓦斯科的兄弟保罗。但他们带回了胡椒和肉桂，城里举行了感恩游行，钟声齐鸣，国王骑马出城迎接他们。人们说，东方的财富从此将经海路而来。",
  "portuguese:build": "1501年，在塔霍河畔的贝伦，热罗尼莫斯修道院开工，它就在瓦斯科·达·伽马的水手们启航前夜祈祷的那座礼拜堂附近。修建费用来自香料贸易税。建筑大师迪奥戈·德·博伊塔卡和若昂·德·卡斯蒂略在它的石头上刻满了绳索、锚、贝壳和海洋生物。修道院的修士们负有为从贝伦出发的水手祈祷的职责。",
  "portuguese:voyage": "多年来，葡萄牙水手都不肯越过非洲海岸的博哈多尔角（Cabo Bojador）；他们说那里的海水沸腾，去了就回不来。1434年，亨利王子的侍从吉尔·埃阿尼斯第二次被派出。他远远地驶向外海，再折回东方，发现自己已经安然越过了海角。他登岸采了野生的迷迭香——人称“圣母玫瑰”（rosas de Santa Maria）——带回去作为证据。",
  "portuguese:festival": "6月12日至13日之夜，里斯本（Lisboa）庆祝本城的圣人圣安东尼（Santo António），他约于1195年出生在这座城市。阿尔法玛和莫拉里亚老城区挂满了纸花环和彩灯；烤架上冒着烟，烤沙丁鱼夹在面包上；一对对恋人在街头随着手风琴起舞。小伙子们送给心上人一盆“曼热里科”（manjerico），那是一小盆罗勒，插着一朵纸康乃馨和一首小情诗。",
  "portuguese:games": "在米尼奥的山区，年轻人学习“棍术”（jogo do pau），用白蜡木或圣栎做的长棍对打。在集市和朝圣节上，敌对的村庄有时会用棍子互相较量，好手可以同时抵挡好几个对手。师傅们在谷仓和院子里传授这门功夫。它是游戏，是运动，也是防身术，米尼奥的老人或许仍会给你演示他最拿手的一招。",
  "portuguese:drought": "想象：八月的阿连特茹。几个月没有下雨；麦田只剩光秃秃的麦茬，栓皮栎在炎热中一动不动，蓄水池水位很低。傍晚，村里的男人们聚在酒馆里唱起阿连特茹合唱（cante alentejano），那是缓慢的多声部歌曲，一人领唱，众人相和，唱的是土地、炎热和迟迟不来的雨。太阳红红地落下。",
  "portuguese:quake": "1522年10月22日黎明前，一场地震震撼了亚速尔群岛（Açores）的圣米格尔岛，当时岛上的主要城镇弗兰卡杜坎普镇上方的一面山坡崩塌了。一条泥石流在人们熟睡时埋没了城镇；约五千人死去。只剩下几座房屋。幸存者一连几天挖掘寻找亲人，随后把岛的首府迁到了蓬塔德尔加达，并带走了他们的圣像。",
  "portuguese:winter": "想象：一月的埃什特雷拉山。雪覆盖着高山牧场，牧羊人已把羊群赶下山到村里。在石屋里，女人们用冬季母羊的奶做奶酪，用野生蓟花凝乳。牧羊人带着他们的狗——埃什特雷拉山的大山地犬——坐在火边，谈论着狼，谈论着春天来时上山的漫漫长路。",
  "portuguese:plague": "1505年，瘟疫袭击里斯本之后，国王曼努埃尔向威尼斯求取一件圣洛克（São Roque）的圣髑，这位朝圣圣人护佑人们免受疫病。圣髑送到后，人们在城外埋葬瘟疫死者的山丘上为它建了一座礼拜堂；后来圣洛克教堂就由此发展而来。几百年来，每逢瘟疫之年，里斯本人都到那里祈祷，求疫病绕过他们。",
  "portuguese:wedding": "在米尼奥，传统的新娘穿黑色：一件缀满黑珠的天鹅绒裙子，一条白色蕾丝头纱，脖子上挂着沉甸甸的金银丝细工饰品——心形、十字架和链子，由她的母亲和祖母传下来。这些黄金显示着家人对她的珍爱。婚礼队伍在六角手风琴和鼓组成的乐队伴奏下走向礼拜堂，宴席一直持续到天亮。",

  "italians:siege": "1529年10月至1530年8月，佛罗伦萨（Firenze）被帝国和教宗的军队围困。负责防务的米开朗琪罗在圣米尼亚托大殿周围修筑了土垒，还把它的钟楼用羊毛床垫裹起来，让炮弹弹开。城墙之内，粮食耗尽，人们吃猫和老鼠，夏天又来了瘟疫。八月，城市投降，饥肠辘辘，却未屈服。",
  "italians:triumph": "想象：一艘威尼斯桨帆船在海上度过漫长的夏天后，划回威尼斯（Venezia）的潟湖。经过利多岛时，圣马可的钟声响起，小船纷纷驶出相迎。桨手们——这座城市的自由民——站起身来，向斯拉夫人堤岸上的家人挥手。那天夜里，卡斯泰洛区的酒馆里满是歌声，女人们清点着薪饷。",
  "italians:build": "1420年，菲利波·布鲁内莱斯基开始建造佛罗伦萨大教堂圣母百花大教堂的穹顶，不用从地面搭起的木脚手架——这是谁都认为不可能的壮举。他设计了牛力驱动的起重机，并以人字形砌法铺砌砖块。石匠们就在穹顶上吃午饭、喝掺水的葡萄酒，以免爬上爬下浪费时间。1436年3月25日，教堂在纪尧姆·迪费的经文歌《玫瑰新近绽放》（Nuper rosarum flores）声中祝圣。",
  "italians:voyage": "1880年至1915年间，约四百万意大利人横渡大西洋前往美洲，其中大多来自南方：坎帕尼亚、卡拉布里亚（Calàbbria）和西西里的农民，带着一只箱子、几句英语和一封表亲的信。从那不勒斯（Napoli）出发的三等舱航程要两个星期。当自由女神像出现在纽约港时，乘客们哭着、欢呼着、画着十字，母亲们把孩子举起来看。",
  "italians:festival": "威尼斯（Venezia）的狂欢节（Carnevale）曾经要持续好几个星期，从圣斯德望节一直到圣灰星期三。戴上面具——鲍塔（bauta）和莫雷塔（moretta）——富人与穷人、贵族与仆人在广场上自由混杂。“肥美星期四”（Giovedì Grasso）那天，人们在小广场上斩下一头公牛的头，杂技演员叠起人塔，称为“赫拉克勒斯之力”（Forze d'Ercole）。忏悔星期二午夜，葡萄园圣方济各教堂的钟声响起，全城收起了面具。",
  "italians:games": "1530年2月17日，围城期间，佛罗伦萨的年轻人在圣十字广场上踢了一场古典足球（calcio storico），乐师们在教堂屋顶上奏乐，让围城的军队也能听见。这是一种每队二十七人的球赛，融合了足球、橄榄球和摔跤。佛罗伦萨至今每年六月仍在同一个广场上比赛，城中四个古老的街区各穿各的颜色。",
  "italians:drought": "想象：干旱的夏天把普利亚（Puglia）的塔沃列雷平原烤成褐色，麦子长得稀稀拉拉。在一个村庄里，人们把主保圣人的雕像从教堂里抬出来，绕着尘土飞扬的田地走，让他亲眼看看龟裂的土地。雨还是不来，有人便威胁要把他留在太阳底下，直到他听进去为止。",
  "italians:quake": "1703年2月2日圣烛节（la Candelora），一场大地震袭击了阿布鲁佐山区的拉奎拉。圣多明我教堂在弥撒中倒塌，压死了数百名前来让蜡烛受祝福的信徒。城市大部分被毁。整个地区约有六千人死亡。幸存者重建了他们的教堂，城中的节庆和游行在帐篷里继续进行。",
  "italians:winter": "1709年1月，威尼斯潟湖冻得结结实实，人们从城里踏冰走到大陆上的梅斯特雷。树木冻裂，发出枪声般的爆响，托斯卡纳（Toscana）的橄榄林冻死，狼从亚平宁山脉下到村庄里。在城市里，穷人烧家具取暖，教会开设施粥所，让饥饿的人活下去。",
  "italians:plague": "1348年，黑死病来到佛罗伦萨，几个月内全城一半以上的人死去。乔万尼·薄伽丘在《十日谈》中描述了这一切：尸体堆在教堂墓地里，家人彼此抛弃，而七位年轻女子和三位年轻男子离开城市去了山上的一座别墅，在城市于山下死去的时候，用十天时间彼此讲了一百个故事。",
  "italians:wedding": "在文艺复兴时期的佛罗伦萨，新娘骑马穿过街道被送往丈夫家，她的嫁妆和衣物装在一对彩绘木箱（cassoni）里跟在后面，箱上画着爱情和美德的场景。宾客们会收到糖衣杏仁（confetti），五颗一份，寓意健康、财富、幸福、子嗣和长寿。丈夫家的宴席要持续好几天，乐师们为舞蹈伴奏。",

  "sicilians:siege": "1282年，西西里晚祷（Vespri siciliani）之后，墨西拿城（Missina）遭到海陆围攻。每个市民都参与了防守。传说有两个女人迪娜和克拉伦扎在夜里看见敌人逼近：迪娜用石头把他们打退，克拉伦扎则敲响大教堂的钟唤醒全城。墨西拿大教堂的巨大天文钟至今仍以她们的形象报时，纪念着她们。",
  "sicilians:triumph": "公元前480年，西西里的希腊城邦在希梅拉大败迦太基军队。狄奥多罗斯写道，俘虏被分给各城邦，被迫修建神庙。在阿克拉加斯（Agrigento, Girgenti），他们建起了宏伟的奥林匹亚宙斯神庙，屋顶由石头巨人支撑。多年间，西西里的农民在田里役使俘虏，各城邦举行感恩节庆。",
  "sicilians:build": "从1174年起，诺曼国王威廉二世在巴勒莫（Palermu）上方的蒙雷阿莱修建了一座大教堂。希腊镶嵌画师用整部圣经的金色图像覆盖了它的墙壁，阿拉伯-西西里工匠则为它的回廊打造了镶嵌着闪亮石子的成对立柱。诺曼、希腊和阿拉伯工匠在短短几年内共同建成了它。阳光透过窗户照进来时，整座教堂金光闪闪，基督从后殿俯视着众人。",
  "sicilians:voyage": "据修昔底德记载，公元前734年，来自科林斯的移民在阿基亚斯率领下向西横渡伊奥尼亚海，寻找新的土地。他们先到达西西里海岸冒着烟的埃特纳火山（Mungibeddu）附近，然后在奥提伽岛上建立了叙拉古城（Siracusa, Sarausa），那里的海边涌出一眼淡水泉——阿瑞图萨泉（Aretusa）。他们的后代建起了西方最伟大的希腊城市。",
  "sicilians:festival": "每年二月，卡塔尼亚都要庆祝主保圣女圣阿加莎（Sant'Àita），她于251年在这里殉道。全城一连三天抬着她的银质圣髑盒穿街过巷，由数千名身穿白袍、头戴黑帽的信徒（devoti）用绳子拉着，高呼：“市民们，圣阿加莎万岁！”（Cittadini, viva Sant'Àita!）各行会抬着巨大的雕花烛塔（candelore）走在她前面，摇摆着、舞动着。烟花照亮了埃特纳火山上空。",
  "sicilians:games": "想象：在西西里山区一个村庄的节日里，年轻人骑着没有鞍的驴沿着大街赛跑，人群欢呼，乐队奏乐。然后是爬油杆，杆顶绑着一只火腿和一块奶酪。男孩们往上爬，滑下来，踩着彼此的肩膀再爬，终于有一个人够到了奖品，把它高高举起，全村一片欢呼。",
  "sicilians:drought": "想象：一个西西里村庄从春天起就没下过雨。山坡上的麦子被晒焦了，蓄水池空了。人们抬着主保圣人的雕像游行，还不下雨，就把圣人转过去面朝大海，或者摘走他的银冠，像数落一个忘了本分的家人一样数落他。等终于下雨了，他们又奏着音乐把他请回来。",
  "sicilians:quake": "1968年1月14日至15日夜，一场地震摧毁了西西里（Sicilia）西部贝利切河谷的城镇：吉贝利纳、波焦雷亚莱、萨拉帕鲁塔、蒙泰瓦戈。约四百人死亡，数万人在冬雨中睡在帐篷里。许多人在棚屋里等了好些年才住上新房。后来，艺术家阿尔贝托·布里在老吉贝利纳的废墟上浇筑了一大片白色混凝土——“裂缝”（Cretto），沿着消失的街道的走向。",
  "sicilians:winter": "整个冬天，埃特纳火山（Mungibeddu）周围村庄的男人们爬上山去收集雪，把雪压进叫作“雪窖”（neviere）的石坑里，盖上灰和稻草。到了夏天，他们把雪挖出来，用骡子驮下山运到城里，为巴勒莫和卡塔尼亚的饮料降温，做成冰沙（granita）。山中冬天的寒冷，变成了西西里夏天的甜蜜。",
  "sicilians:plague": "1743年春，一艘来自希腊的船把瘟疫带到了墨西拿（Missina）。它在城中蔓延得比谁都数得过来还快。几个月内约四万人死去，或许每三人中就有两人。富人逃往山上，神父们把死者埋在海边的壕沟里，幸存者抬着城市的守护者“书信圣母”（Madonna della Lettera）穿过空荡荡的街道，祈求疫病结束。",
  "sicilians:wedding": "在旧时的西西里，婚礼之前，新娘的嫁妆（corredo）会摆在娘家，让所有邻居观看：床单、毛巾和睡袍，全是她和母亲多年来亲手绣的。婚礼当天，新娘（zita）和家人一起走向教堂。宴席上有音乐和舞蹈，宾客们吃着奶油甜卷（cannoli）、卡萨塔蛋糕（cassata）和杏仁甜点，直到深夜。",

  "maltese:siege": "到1942年8月，被围困的马耳他正在挨饿；面包配给被削减，“胜利厨房”供应着稀薄的汤。一支船队奋战突围而来，8月15日圣母升天节（Santa Marija），受了重创的油轮“俄亥俄号”被两艘驱逐舰夹着拖进大港（il-Port il-Kbir），甲板几乎没入水中。人群站满了瓦莱塔（il-Belt Valletta）的城堡，欢呼、祈祷、流泪。马耳他人至今仍称之为“圣母升天节船队”（il-Konvoj ta' Santa Marija）。",
  "maltese:triumph": "1565年9月8日，大围攻（l-Assedju l-Kbir）结束，奥斯曼舰队撤走了。每一座尚存的教堂都敲响了钟，大团长让·德·瓦莱特和比尔古（il-Birgu）的百姓前往圣劳伦斯教堂唱《赞美颂》。饥饿而负伤的人们从城镇的废墟中走出来。在这一天——胜利日（Il-Vittorja）——马耳他人至今仍在大港举行划船比赛。",
  "maltese:build": "戈佐岛（Għawdex）的吉甘提亚神庙建于五千多年前，是世界上最古老的石建筑之一。它们的巨石重达数吨。戈佐人传说，是一个名叫桑苏娜的女巨人建造了它们，她一边给婴儿喂奶，一边用头顶着石头，靠吃豆子喝水为生。考古学家则说，是整个整个的村社一起把石头拖来的，下面垫着圆石滚动。",
  "maltese:voyage": "想象：1950年代，一个来自泽伊通的家庭在大港（il-Port il-Kbir）登上一艘开往澳大利亚的船。亲戚们在城堡上挥手，父亲的母亲哭着给了他一张小小的圣母像。在海上航行数周、横渡印度洋之后，澳大利亚的海岸从晨雾中升起。孩子们冲到栏杆边，母亲用马耳他语念起了玫瑰经。",
  "maltese:festival": "夏天，马耳他的每个村庄都为主保圣人举办节庆（festa）。街道上挂满旗帜和彩灯，教堂里烛光闪耀、红锦缎生辉，铜管乐队在街上行进。正日那天，圣人像在人群和花瓣中被抬出来，村里志愿者自制的烟花在头顶炸响。人人都从街边摊上买来牛轧糖（qubbajt）吃。",
  "maltese:games": "在圣朱利安（San Ġiljan）节和其他夏季节庆上，年轻人挑战“油杆”（ġostra）：一根伸出港口海面的涂油长杆。他们沿杆奔跑去抓杆头的旗子，在人群的欢呼声中滑倒、掉进海里。9月8日的赛艇会（ir-Regatta）上，各城镇在大港进行划船比赛，船只漆着各自的颜色，城堡上挤满了观众。",
  "maltese:drought": "马耳他没有河流，干旱的夏天里，瓦莱塔（il-Belt Valletta）全靠蓄水池和挑水人。1610年，大团长阿洛夫·德·维尼亚古尔开始修建一条水道，把姆迪纳（l-Imdina）附近山中的泉水引到新城。1615年4月21日，水流到了瓦莱塔，从主广场的喷泉中涌出。人群纷纷前来饮水谢恩。",
  "maltese:quake": "1693年1月11日，一场大地震袭击了西西里东南部，整个马耳他都有震感。在姆迪纳（l-Imdina），古老的圣保罗大教堂严重受损，许多房屋倒塌。马耳他无人死亡，但人们惊恐万分。建筑师洛伦佐·加法以巴洛克风格重建了大教堂，那座宏伟的穹顶至今仍高耸在老城的城墙之上。",
  "maltese:winter": "想象：一月，东北风（gregale）把灰色的浪头赶进港湾。马尔萨什洛克的渔民把他们的卢祖船（luzzu）拖上岸修补渔网，船头画着的眼睛注视着风暴。傍晚，男人们坐在乐队俱乐部里，一位老人唱起即兴民歌（għana），另一人用吉他应和。",
  "maltese:plague": "1813年，一艘来自亚历山大港的船把瘟疫带到了马耳他。它在瓦莱塔（il-Belt Valletta）和各村庄蔓延；约四千五百人死亡。房屋被关闭封死，病人被送往马诺埃尔岛上的检疫所，死者被埋在石灰坑里。人们向圣洛克（San Rokku）祈祷。疫病过去后，他们建起了谢恩的礼拜堂。",
  "maltese:wedding": "想象：一个村庄里的老式马耳他婚礼。新娘的母亲多年来为她准备好了亚麻织品和家具。婚礼在新娘所在教区的教堂举行，钟声向全村宣告喜讯，新娘挽着父亲走向教堂。之后两家人在家中相聚设宴，有馅饼（pastizzi）、炖兔肉和甜点，男人们唱着即兴民歌（għana）直到深夜。",
  "britons:showcase": "希腊和罗马作家描述过凯尔特吟游诗人，他们弹着里拉琴赞颂或嘲讽自己的领主。在中世纪的威尔士（Cymru），诗人和竖琴手在宫廷中享有尊荣的地位；1176年，里斯勋爵在卡迪根（Aberteifi）召集诗人和乐师举行比赛，这被铭记为第一届诗歌音乐节（eisteddfod）。约1190年，威尔士的杰拉尔德称赞威尔士人的多声部合唱，并提到了竖琴、克鲁斯琴（crwth）和笛管。约1613年抄写的罗伯特·阿普·休手稿用其独有的记谱法保存了古老的竖琴音乐。三排弦竖琴于17世纪传入，成为威尔士竖琴；克鲁斯琴和皮布格恩角笛（pibgorn）约在1800年前后式微，如今又重新被人演奏。“琴弦之歌”（cerdd dant），即配着竖琴曲调吟唱诗句，至今仍活跃在诗歌音乐节的舞台上。",
  "english:showcase": "最早的英格兰音乐只能透过出土文物和古籍去聆听：7世纪初埋在萨顿胡的一把里拉琴，以及13世纪抄写的轮唱曲《夏日来临》（Sumer is icumen in），已知最古老的卡农之一。吟游乐人演奏提琴、吉特恩琴、索尔特里琴和风笛；乔叟笔下的磨坊主吹着风笛领着朝圣者出城。约1400年，王家礼拜堂的曲目被汇集在《老厅手稿》中，阿金库尔颂歌《感谢上帝，英格兰》（Deo gratias Anglia）此后不久便被传唱。约翰·邓斯泰布尔甜美的三度和六度——“英国风格”——在海峡对岸备受推崇。号角和铜鼓（nakers）为游行和比武鸣响，教堂钟声标记时辰，萨克布号也加入了城镇乐队。如今，颂歌、转调鸣钟和复兴的古乐合奏团延续着那种声音。",
  "house-of-lancaster:showcase": "约1500年，《伊顿合唱曲集》汇集了恢宏的多声部英格兰复调音乐，亨利八世的宫廷养着数十名乐师；他死后编制的一份清单列有大量的竖笛、维奥尔琴、鲁特琴和肖姆管。托马斯·塔利斯和威廉·伯德为教堂和室内创作，维奥尔琴合奏团在大宅中演奏幻想曲和《以主之名》（In Nomine）。城镇出钱雇用吹奏肖姆管和萨克布号的更夫乐队（waits）在街头和市政宴会上演奏。《绿袖子》于1580年作为民谣登记，约翰·道兰的《歌曲第一集》（1597年）使鲁特琴歌曲名扬一时。这种声音在18世纪渐渐消失，但从19世纪末起，阿诺德·多尔梅奇重新制作了鲁特琴、维奥尔琴和竖笛，如今大教堂唱诗班和早期音乐合奏团仍在演奏这些曲目。",
  "celts:showcase": "铁器时代的凯尔特人吹奏卡尼克斯号（carnyx），一种高大的青铜战号，号口铸成兽头；在苏格兰的德斯克福德和高卢的坦蒂尼亚克都发现过残件。青铜时代晚期的爱尔兰留下了许多铸造的号角，古爱尔兰语文献提到了“多尔德”（dord）。早期的里拉琴让位于金属弦竖琴（cláirseach, clàrsach），由世袭的竖琴手用指甲弹奏；三一学院竖琴和玛丽王后竖琴是中世纪晚期的遗存。图尔洛·奥卡罗兰（Toirdhealbhach Ó Cearbhalláin）直到1730年代仍在为赞助人作曲，爱德华·邦廷于1792年在贝尔法斯特记录下了最后一批老竖琴手的曲调。高地风笛（pìob mhòr）及其“皮布罗赫”（piobaireachd）、小提琴、伊利安风笛和宝思兰鼓（bodhrán）是后来才出现的。如今，即兴聚奏（session）、古风清唱（sean-nós）和赫布里底群岛的缩绒歌（òrain luaidh）让这音乐继续存活。",
  "franks:showcase": "早期法兰克音乐所知甚少，只有阿尔卑斯山以北中世纪早期墓葬中出土的那类里拉琴。750年代，丕平和后来的查理曼让他们的歌手学习罗马圣咏，它与更古老的高卢圣咏融合，成为我们所说的格里高利圣咏。757年，一位拜占庭皇帝送给丕平一架管风琴，这在西方是一大奇观。9世纪，抄写员开始用纽姆符记写旋律，论著《音乐手册》（Musica enchiriadis）描述了奥尔加农（organum），即西方最早见诸文字的复调音乐。后来又有了象牙号角（olifant）——《罗兰之歌》中罗兰吹响的那支，有维埃尔琴（vièle），还有1188年雕刻在圣地亚哥的奥尔加尼斯特鲁姆琴（organistrum）。19世纪，索莱姆的修士们复兴了圣咏，至今仍被传唱。",
  "french:showcase": "中世纪的法国音乐源于两处：一是游吟诗人（troubadour与trouvère），他们伴着维埃尔琴唱情歌；一是巴黎圣母院，约1200年，莱奥南和佩罗坦在那里构建了宏大的奥尔加农。14世纪，纪尧姆·德·马肖创作了歌曲和一部完整的弥撒曲。在宫廷里，“国王的二十四把提琴”（Vingt-quatre Violons du Roi）于1620年代成为国王的弦乐队，让-巴蒂斯特·吕利使之名扬天下；库普兰和拉莫为羽管键琴（clavecin）作曲。廷臣们穿着田园装束演奏风笛（musette）和手摇弦琴（vielle à roue），狩猎号角（cors de chasse）在森林中呼唤，横笛和鼓伴着卫队行进。如今，手摇弦琴和卡布雷特风笛（cabrette）仍在奥弗涅和贝里演奏布雷舞曲，狩猎号角手们也仍在聚会。",
  "jeanne-darc:showcase": "8世纪，主教克罗德冈把罗马圣咏带到梅斯，那里的歌唱学校成了法兰克各地最受推崇的学校之一；“洛林”或“梅斯”纽姆符——一种记写圣咏的方式——便由此得名。整个中世纪，该地区的修道院和大教堂吟唱日课和弥撒，管风琴和教堂钟声标记着时辰。到了15世纪贞德的时代，吟游乐人演奏维埃尔琴、索尔特里琴、吉特恩琴和竖笛，长号（buisine）和号角为军队和入城仪式吹响。贞德本人说，她最常在钟声响起时听到那些声音。她家乡村庄的音乐没有留存下来，因此这首曲子是一种重构；素歌至今仍在该地区的教堂中吟唱。",
  "knights-templar:showcase": "格里高利圣咏（cantus planus）源于早期基督徒团体的诗篇吟唱，在8至9世纪被塑造成一套在整个拉丁欧洲传唱的曲目。修士们最初用纽姆符记写它；约1025年，阿雷佐的圭多教歌手们读谱表线上的音符，并把音名定为ut、re、mi。奥尔加农增添了第二个声部，从《温切斯特附加段集》一直到巴黎圣母院的莱奥南和佩罗坦。12世纪的骑士修会，包括圣殿骑士团，像修士一样吟唱每日的日课。雷贝克琴源自阿拉伯的拉巴卜琴（رباب），铜鼓（nakers）源自纳卡拉鼓（نقارة）。经过数百年的修订之后，索莱姆的修士们在19世纪恢复了古老的旋律，各修道院至今仍每日吟唱。",
  "burgundians:showcase": "从1360年代到1477年，瓦卢瓦王朝的勃艮第公爵们拥有欧洲最富丽的礼拜堂乐团之一。吉勒·班舒瓦侍奉好人腓力，纪尧姆·迪费为他的宫廷作曲，安托万·比斯努瓦则为大胆查理作曲。他们的尚松和弥撒曲开启了法兰德斯复调的时代。宫廷音乐分为“高音”（haute）和“低音”（basse）：前者是由肖姆管、邦巴尔德管和萨克布号组成的响亮的阿尔塔乐队（alta capella），用于舞蹈和户外；后者是竖琴、鲁特琴、竖笛、维埃尔琴和便携管风琴，柔和地用于室内。编年史家记载，在1454年的雉鸡宴上，乐师们从一个巨大的馅饼里面演奏。后来在这一传统中成长的作曲家们活跃于全欧洲；肖姆管的声音至今仍回响在布列塔尼的邦巴尔德管和加泰罗尼亚的科布拉乐队（cobla）中。",
  "dutch:showcase": "低地国家培养了15、16世纪许多伟大的复调作曲家，如雅各布·奥布雷赫特，也为每一座教堂钟楼铸钟。1640年代，海莫尼兄弟与乌得勒支的盲人钟琴师雅各布·范艾克合作，学会了精确地为钟调音，调音钟琴（beiaard）由此诞生。范艾克还在教堂墓地为散步的人吹奏竖笛变奏曲，并将其印成《笛之乐园》（Der Fluyten Lust-hof）。阿姆斯特丹老教堂的管风琴师扬·彼得松·斯韦林克举行公开演奏会，远方的管风琴师纷纷前来拜师。教堂里唱诗篇，家中弹奏西特琴和鲁特琴，安特卫普的鲁克斯家族制造羽管键琴。如今，钟琴声回荡在荷兰各城镇，手摇街头风琴（draaiorgels）在广场上演奏。",
  "spanish:showcase": "13世纪阿方索十世宫廷编纂的《圣母玛利亚颂歌集》（Cantigas de Santa María），其插图中画有数十位乐师，演奏着鲁特琴、雷贝克琴、风笛、竖琴和鼓，其中许多乐器来自安达卢斯：劳德琴（laúd）源自乌德琴（العود），阿塔巴尔鼓（atabal）源自塔卜勒鼓（الطبل）。16世纪，路易斯·德·米兰等比维拉琴（vihuela）演奏家出版了幻想曲集，而大教堂的器乐手（ministriles）则吹奏着肖姆管（chirimías）和萨克布号（sacabuches），与演唱莫拉莱斯、格雷罗和维多利亚作品的唱诗班相伴。五组弦的西班牙吉他在17世纪流行开来，加斯帕尔·桑斯1674年的教本便教授这种乐器。19世纪的安达卢西亚，吉卜赛（Gitano）歌手和吉他手塑造了弗拉门戈。如今，吉他、响板、加利西亚风笛（gaita）以及巴斯克的奇斯图笛（txistu）和它的鼓，都是活着的传统。",
  "portuguese:showcase": "最古老的葡萄牙歌曲是13世纪用加利西亚-葡萄牙语演唱的“友人之歌”（cantigas de amigo）；马丁·科达克斯的七首歌保存在一张羊皮纸上，其中六首附有乐谱。国王迪尼斯本人就是一位游吟诗人。16、17世纪，埃武拉和里斯本的大教堂与修道院唱诗班演唱杜阿尔特·洛博和曼努埃尔·卡多索的复调作品，而号角和鼓则随着卡拉维尔帆船远航。水手和移民把小巧的卡瓦奇尼奥琴（cavaquinho）带到马德拉及更远的地方，它在那里成为尤克里里的祖先之一。19世纪，里斯本的港口街区出现了法多（fado），伴着中提吉他（viola）和十二弦的葡萄牙吉他（guitarra portuguesa）演唱。如今，法多、男声的阿连特茹合唱（cante alentejano）和北方节庆上的大鼓（bombos）都依然鲜活。",
  "italians:showcase": "约1025年，阿雷佐的圭多教歌手们读谱表上的音符；14世纪的佛罗伦萨，盲人管风琴师弗朗切斯科·兰迪尼创作了叙事歌（ballate）和牧歌。16世纪，安德烈亚·加布里埃利和乔万尼·加布里埃利让唱诗班、短号（cornetti）和长号在威尼斯圣马可大教堂的两侧遥相对答。歌剧约于1600年诞生于佛罗伦萨，1607年蒙特威尔第的《奥菲欧》在曼托瓦上演，用上了双颈鲁特琴（theorbo）、维奥尔琴和通奏低音。在克雷莫纳，阿马蒂、斯特拉迪瓦里和瓜奈里家族制作的小提琴至今仍备受珍视，科雷利和维瓦尔第则使小提琴成为协奏曲的主角。18世纪，那不勒斯赋予了曼陀林经典的形制，19世纪则属于歌剧。如今，克雷莫纳的工坊和意大利的歌剧院延续着这份音乐。",
  "sicilians:showcase": "西西里的希腊移民吹奏阿夫洛斯管（αὐλός）、弹奏里拉琴，后来统治该岛的阿拉伯人称它为西西里亚（صقلية），把他们的鲁特琴和鼓带进了岛上的城镇。在12世纪的诺曼国王治下，阿拉伯、希腊和拉丁乐师在巴勒莫宫廷供职，但他们的音乐没有一首被记录下来。流传下来的，是牧羊人和市井百姓口耳相传的东西：圣诞九日敬礼时吹奏的赞波尼亚风笛（zampogna）和恰拉梅拉管（ciaramella）；弗里斯卡莱图芦笛（friscalettu）；还有马兰扎努口簧琴（marranzanu）。圣周时善会吟唱哀歌，说唱艺人（cantastorie）在广场上唱新闻和传说，塔兰泰拉舞曲让人们的脚动起来。如今，曼陀林、小手鼓（tamburelli）、节庆的鼓和教堂钟声充满了岛上的节日。",
  "maltese:showcase": "关于马耳他史前神庙建造者的音乐，我们几乎一无所知。几个世纪的阿拉伯统治留下了马耳他语，也留下了古老的民间乐器：山羊皮风笛扎克（żaqq）、框鼓坦布尔（tanbur）、摩擦鼓扎夫扎法（żafżafa）和芦笛弗莱古塔（flejguta）。1530年至1798年统治这些岛屿的圣约翰骑士团带来了巴洛克教堂音乐，姆迪纳（l-Imdina）大教堂保存着那个时代的大量乐谱档案。19世纪，各村庄成立了乐队俱乐部，节庆铜管乐队成了夏日节庆的声音。“加纳”（għana）是伴着吉他吟唱的诗句，其中包括即兴对歌比赛“斯皮尔图·普龙特”（spirtu pront）。如今，乐队、教区唱诗班和管风琴仍在演奏，扎克风笛也已复兴。",
});
